384	    private static ToIntFunction<Claim> grace(Function<String, DatedSetting> ofGrade, LongFunction<Person> person) {
385	        Map<String, DatedSetting> graces = new HashMap<>();
386	        Map<Long, Optional<Person>> persons = new HashMap<>();
387	        return (claim) -> {
388	            Person p = persons.computeIfAbsent(claim.getPersonId(), (id) -> Optional.ofNullable(person.apply(id))).orElse(null);
389	            if (p == null) return 0;
390	            String grade = p.gradeOn(claim.getDate());
391	            if (grade == null) return 0;
392	            String days = graces.computeIfAbsent(grade, ofGrade).on(claim.getDate());
393	            return days == null ? 0 : Integer.parseInt(days);
