46	        if (SettingRepository.CLERK_LIMIT.equals(key)) {
47	            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
48	                throw new InvalidSettingException("The clerk limit is blank or 0.00 or more with up to two decimals");
49	            }
50	        } else if (key.startsWith(SettingRepository.CLERK_LIMIT_OF_GRADE)
51	                && gradeCodes.contains(key.substring(SettingRepository.CLERK_LIMIT_OF_GRADE.length()))) {
52	            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
53	                throw new InvalidSettingException("A grade's clerk limit is blank or 0.00 or more with up to two decimals");
54	            }
55	        } else if (SettingRepository.PROOF_THRESHOLD.equals(key)) {
56	            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
57	                throw new InvalidSettingException("The proof threshold is blank or 0.00 or more with up to two decimals");
58	            }
59	        } else if (key.startsWith(SettingRepository.PROOF_THRESHOLD_OF_GRADE)
60	                && gradeCodes.contains(key.substring(SettingRepository.PROOF_THRESHOLD_OF_GRADE.length()))) {
61	            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
62	                throw new InvalidSettingException("A grade's proof threshold is blank or 0.00 or more with up to two decimals");
63	            }
64	        } else if (SettingRepository.PROOF_KINDS.equals(key)) {
65	            List<String> kinds = value.isEmpty() ? List.of()
66	                    : Arrays.stream(value.split(",")).map(String::trim).distinct().toList();
67	            if (!kinds.stream().allMatch(ProofKind.ALL::contains)) {
68	                throw new InvalidSettingException("The proof kinds are blank or a comma separated list of receipt and photo");
69	            }
