71	            return;
72	        } else if (SettingRepository.NOTE_THRESHOLD.equals(key)) {
73	            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
74	                throw new InvalidSettingException("The note threshold is blank or 0.00 or more with up to two decimals");
75	            }
76	        } else if (SettingRepository.REVIEW_THRESHOLD.equals(key)) {
77	            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
78	                throw new InvalidSettingException("The review threshold is blank or 0.00 or more with up to two decimals");
79	            }
80	        } else if (SettingRepository.CAP.equals(key)) {
81	            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
82	                throw new InvalidSettingException("The cap is blank or 0.00 or more with up to two decimals");
83	            }
84	        } else if (SettingRepository.POT.equals(key)) {
85	            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
86	                throw new InvalidSettingException("The pot is blank or 0.00 or more with up to two decimals");
