90	        } else if (SettingRepository.ALERT_THRESHOLD.equals(key)) {
91	            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
92	                throw new InvalidSettingException("The alert threshold is blank or 0.00 or more with up to two decimals");
