155	                throw new InvalidSettingException("The score log is on or blank");
156	            }
157	            body.set(new SettingRequest(key, value.isEmpty() ? null : value, null));
158	            return;
159	        } else if (SettingRepository.GRACE_DAYS.equals(key)) {
160	            if (!value.isEmpty() && !DAYS.matcher(value).matches()) {
161	                throw new InvalidSettingException("The grace days are blank or a whole number of days, 0 or more");
162	            }
163	            body.set(new SettingRequest(key, value.isEmpty() ? null : String.valueOf(Integer.parseInt(value)), null));
