1	import { getJson, postJson, putJson } from '../../api/http';
2	import { sheetKey } from '../sheet/api';
3	
4	/** A claim's status: DRAFT, opened to OPEN, settled to SETTLED (or, by a clerk above the clerk limit,
5	 *  to PENDING, which a steward approves to SETTLED or rejects back to OPEN); a DRAFT, OPEN or PENDING
6	 *  claim can be voided, and a SETTLED one by a steward within 7 days of its settlement. A DRAFT can be
7	 *  deleted to DELETED (counted nowhere), and restored to DRAFT on the sheet's today it was deleted. A DRAFT
8	 *  whose due is above the review threshold in force on its date opens to REVIEW instead (counted nowhere,
9	 *  unnumbered), which a steward reviews to OPEN; a REVIEW claim can be voided. */
10	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED' | 'REVIEW';
11	/** A change of a claim's status. */
12	export type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject' | 'resettle' | 'delete' | 'restore' | 'review';
13	
14	/** Whether a claim is open: OPEN, or PENDING a steward's approval. */
15	export const isOpen = (c: Pick<Claim, 'status'>) => c.status === 'OPEN' || c.status === 'PENDING';
16	
17	/** Whether a statement's figure binds a claim now: it was bound to one (a PENDING claim too). */
18	export const isBound = (c: Claim) => c.stated && c.statedDue !== null;
19	
20	/** A claim: its amount as two-decimal text, its date (yyyy-MM-dd), its note, its status and its
21	 *  number on the sheet (given when opened: the sheet-wide 1, 2, ... or, under period numbering,
22	 *  <period>-<n> or X-<n>; null while a draft), and its settled due
23	 *  (fixed when settled; null otherwise, or when there was no rate then — its due stays live), and who
24	 *  opened it (null while a draft; that user cannot settle it), and whether its person's last statement
25	 *  bound it, with the figure it bound (null when it had none): a bound claim shows and totals that.
26	 *  A correction (a negative amount) has the number of the SETTLED claim it corrects (null otherwise).
27	 *  `roundDate` is the date its live figures round by: its own, or a correction's claim's it corrects.
28	 *  `dueBy` (yyyy-MM-dd) is fixed when it was added: its date then plus the terms in force on the
29	 *  sheet's today then (the person's own, else their grade's that day, else the sheet's). `log` is its status log, oldest
30	 *  first: `<STATUS> by <user> on <date> due=<due>`, the sheet's today and its due at each change.
31	 *  `deferredUntil` is the date it was last deferred until (null: never), and `deferred` whether it is
32	 *  deferred on the sheet's today (OPEN, or VOID voided while deferred, or SETTLED settled while bound after it was deferred;
33	 *  not bound by a statement — a bound claim's deferral takes effect once the binding ends; and deferred until a later date): a deferred claim counts in no
34	 *  total, is not overdue, cannot be settled and is left unbound by a statement. `proofs` is how many
35	 *  proofs it has, `photoProofs` how many of them are photos (the rest are receipts): one whose due is
36	 *  above the proof threshold in force on its date cannot be settled or approved with none (while the
37	 *  sheet's proof kinds are set: with none of one of them). */
38	export type Claim = {
39	  id: number; sheetId: string; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
40	  number: string | null; settledDue: string | null; openedBy: string | null;
41	  stated: boolean; statedDue: string | null; corrects: string | null; roundDate: string; dueBy: string;
42	  log: string[]; deferredUntil: string | null; deferred: boolean; proofs: number; photoProofs: number;
43	  /** Its comments, oldest first: `<user> on <date>: <text>` (the sheet's today when written). */
44	  comments: string[];
45	  /** Its lines, in the order they were added: `<label> <qty> x <unit>`; with lines, its amount is their total. */
46	  lines: string[];
47	  /** The number of the claim it was split from (null: not split off a claim). */
48	  splitFrom: string | null;
49	  /** The user whose open editor locks it for everyone else (null: unlocked). */
50	  lockedBy: string | null;
51	  /** Whether it was added while the period its due-by falls in was soft-closed. */
52	  lateEntry: boolean;
53	  /** The last sheet's today it was reminded on (null: never reminded). */
54	  reminded: string | null;
55	  /** Whether a steward waived its late charge: it bears none from then on, whatever its overdue state. */
56	  waived: boolean;
57	  /** The user a steward assigned it to review (null: never assigned); kept once it is reviewed. */
58	  reviewAssignee: string | null;
59	  /** Whether it is held: shown only; a held claim counts in every total as any other. */
60	  held: boolean;
61	  /** Its external reference (null: none); used once per sheet, compared without regard to case. */
62	  ref: string | null;
63	  /** Its tags: trimmed, lower-cased, without repeats, sorted and comma separated (null: none). */
64	  tags: string | null;
65	  /** The reason it was voided with, from the sheet's void reasons (null: none). */
66	  voidReason: string | null;
67	  /** The number of the bulk settle batch that settled it (null: not settled by a bulk settle). */
68	  settleBatch: number | null;
69	  /** Its shares held by other people on the sheet, in the order they were added: each holder's id and name and
70	   *  their percent of its due (two decimals). */
71	  shares: ClaimShare[];
72	};
73	/** A share of a claim held by another person on the sheet (see `Claim.shares`). */
74	export type ClaimShare = { personId: number; name: string; share: string };
75	/** `corrects`: the number of the SETTLED claim of the same person a correction (a negative amount) corrects.
76	 *  `ref`: its external reference (trimmed; blank: none), refused when already used on the sheet.
77	 *  `tags`: its tags, comma separated (each trimmed and lower-cased, repeats dropped; blank: none). */
78	export type ClaimInput = { amount: string; date: string; note: string; corrects: string; ref: string; tags: string };
79	
80	/** A claim's tags as shown: sorted, comma and space separated (blank: none). */
81	export const showTags = (tags: string | null) => (tags ?? '').split(',').filter((t) => t !== '').join(', ');
82	
83	/** A claim's tags as a list (empty: none). */
84	export const tagsOf = (c: Pick<Claim, 'tags'>) => (c.tags ?? '').split(',').filter((t) => t !== '');
85	
86	/** Whether a claim corrects another (names the claim it corrects): left out of claimed. */
87	export const correctsAnother = (c: Pick<Claim, 'corrects'>) => !!c.corrects?.trim();
88	
89	/** Whether a claim is a correction: its amount is negative. */
90	export const isCorrection = (c: Pick<Claim, 'amount'>) => c.amount.trim().startsWith('-') && Number(c.amount) !== 0;
91	
92	const sheetBase = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}`;
93	
94	export const claimsKey = (sheetId: string) => [...sheetKey(sheetId), 'claims'] as const;
95	
96	/** Under the claims' key, so whatever refreshes the claims refreshes the tags too. */
97	export const tagsKey = (sheetId: string) => [...claimsKey(sheetId), 'tags'] as const;
98	
99	/** Every tag ever used on the sheet's claims, sorted. */
100	export function listTags(sheetId: string): Promise<string[]> {
101	  return getJson<string[]>(`${sheetBase(sheetId)}/tags`);
102	}
103	
104	/** Every claim on the sheet, newest first. */
105	export function listClaims(sheetId: string, live = false): Promise<Claim[]> {
106	  return getJson<Claim[]>(`${sheetBase(sheetId)}/claims`, live);
107	}
108	
109	/** Add a claim to a person; refused (rejects) when the amount is missing or has more than two
110	 *  decimals, the date is not a date, or it is a correction (negative) that does not name by number a
111	 *  SETTLED claim of the person, or its reference is already used on the sheet (in any case). A blank date takes the sheet's entry date when set, else its today. */
112	export function addClaim(sheetId: string, by: string, personId: number, input: ClaimInput): Promise<Claim> {
113	  return postJson<Claim>(`${sheetBase(sheetId)}/people/${personId}/claims?by=${encodeURIComponent(by)}`, input);
114	}
115	
116	/** Edit a claim; refused (rejects) like an add. */
117	export function updateClaim(sheetId: string, by: string, id: number, input: ClaimInput): Promise<Claim> {
118	  return putJson<Claim>(`${sheetBase(sheetId)}/claims/${id}?by=${encodeURIComponent(by)}`, input);
119	}
120	
121	/** Open a claim's editor, locking it for other users until it is saved or cancelled or the sheet's
122	 *  today changes (and releasing any other claim of its person the user held); refused (rejects) with
123	 *  409 when it is not a DRAFT, 423 when due by a day in a closed period, 412 while another user holds it. */
124	export function lockClaim(sheetId: string, by: string, id: number): Promise<Claim> {
125	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/lock?by=${encodeURIComponent(by)}`, {});
126	}
127	
128	/** Cancel a claim's editor, releasing its lock when the user holds it. */
129	export function unlockClaim(sheetId: string, by: string, id: number): Promise<Claim> {
130	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/unlock?by=${encodeURIComponent(by)}`, {});
131	}
132	
133	/** Change a claim's status; refused (rejects) when its status does not allow the change, when the
134	 *  user settling or approving it is the one who opened it, when a non-steward approves or rejects it,
135	 *  or when a rejection has no `reason`, or a void none from the sheet's void reasons while it has any. A steward's `resettle` freezes a SETTLED claim again at the
136	 *  figure it would have today as an open claim bound by no statement. `delete` makes a DRAFT DELETED (refused for
137	 *  any other status or one due by a day in a closed period); `restore` makes a DELETED claim a DRAFT again,
138	 *  refused on a later sheet's today than the one it was deleted on. A `settle` with a date `on` (blank: the
139	 *  sheet's today) freezes the due as it stood at the end of that day; refused for a date after the sheet's
140	 *  today or a claim that did not exist then. */
141	export function moveClaim(sheetId: string, by: string, id: number, action: ClaimAction, reason = '', on = ''): Promise<Claim> {
142	  const extra = action === 'reject' || action === 'void' ? `&reason=${encodeURIComponent(reason)}`
143	    : action === 'settle' && on !== '' ? `&on=${encodeURIComponent(on)}` : '';
144	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/${action}?by=${encodeURIComponent(by)}${extra}`, {});
145	}
146	
147	/** Defer an OPEN claim until a date after the sheet's today; refused (rejects) when it is not OPEN,
148	 *  the date is not after today, or it is due by a day in a closed period. */
149	export function deferClaim(sheetId: string, by: string, id: number, until: string): Promise<Claim> {
150	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/defer?by=${encodeURIComponent(by)}&until=${encodeURIComponent(until)}`, {});
151	}
152	
153	/** A claim's timeline: the audit lines about it exactly as the file holds them, newest first — those
154	 *  carrying its number, or for a claim with no number those naming its person, amount and date together. */
155	export function claimTimeline(sheetId: string, id: number): Promise<string[]> {
156	  return getJson<string[]>(`${sheetBase(sheetId)}/claims/${id}/timeline`);
157	}
158	
159	/** A steward waives an OPEN or PENDING claim's late charge; refused (rejects) with 409 for anyone else,
160	 *  any other status, or a claim already waived. */
161	export function waiveClaim(sheetId: string, by: string, id: number): Promise<Claim> {
162	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/waive?by=${encodeURIComponent(by)}`, {});
163	}
164	
165	/** A steward assigns a REVIEW claim to a user; refused (rejects) with 409 for anyone else or any other
166	 *  status, 400 for a blank user. */
167	export function assignReview(sheetId: string, by: string, id: number, to: string): Promise<Claim> {
168	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/assign-review?by=${encodeURIComponent(by)}&user=${encodeURIComponent(to)}`, {});
169	}
170	
171	/** Hold an OPEN or PENDING claim, or release it when held; refused (rejects) with 409 for any other status. */
172	export function holdClaim(sheetId: string, by: string, id: number): Promise<Claim> {
173	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/hold?by=${encodeURIComponent(by)}`, {});
174	}
175	
176	/** Remind an OPEN or PENDING claim on the sheet's today; refused (rejects) with 409 for any other
177	 *  status, or when it was already reminded on the sheet's today. */
178	export function remindClaim(sheetId: string, by: string, id: number): Promise<Claim> {
179	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/remind?by=${encodeURIComponent(by)}`, {});
180	}
181	
182	/** A steward re-dates an OPEN or PENDING claim to `date`: its due-by and any bound figure stay, and
183	 *  so do its period (the one its due-by falls in) and its number. Refused (rejects) for anyone else, any other status, a date after its person's
184	 *  retirement, or a claim due by a day in a closed period. */
185	/** A steward sets a DRAFT, OPEN or PENDING claim's due-by directly (yyyy-MM-dd); it stays as set. */
186	export function setClaimDueBy(sheetId: string, by: string, id: number, date: string): Promise<Claim> {
187	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/due-by?by=${encodeURIComponent(by)}&date=${encodeURIComponent(date)}`, {});
188	}
189	
190	export function redateClaim(sheetId: string, by: string, id: number, date: string): Promise<Claim> {
191	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/redate?by=${encodeURIComponent(by)}&date=${encodeURIComponent(date)}`, {});
192	}
193	
194	/** Split an OPEN claim: it keeps the rest of its amount and loses any figure a statement bound it to;
195	 *  a new OPEN claim of `amount` (more than 0.00, less than the claim's), opened by the user, is split
196	 *  from its number. Refused (rejects) for a PENDING, deferred or settled claim, one due by a day in a closed
197	 *  period, an amount out of range, or a role that may not open a claim. */
198	export function splitClaim(sheetId: string, by: string, id: number, amount: string): Promise<Claim> {
199	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/split?by=${encodeURIComponent(by)}&amount=${encodeURIComponent(amount)}`, {});
200	}
201	
202	/** Part-settle an OPEN claim: `amount` is split off as {@link splitClaim} does, and the new claim is settled
203	 *  at once by the user as the settle does (to PENDING by a clerk above the clerk limit); the four-eyes and
204	 *  proof rules are judged on the original claim. A refused split or settle refuses it all. Resolves to the new claim. */
205	export function settlePartClaim(sheetId: string, by: string, id: number, amount: string): Promise<Claim> {
206	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/settle-part?by=${encodeURIComponent(by)}&amount=${encodeURIComponent(amount)}`, {});
207	}
208	
209	/** The kinds a proof may be (none chosen: a receipt). */
210	export const PROOF_KINDS = ['receipt', 'photo'] as const;
211	export type ProofKind = typeof PROOF_KINDS[number];
212	
213	/** How many of a claim's proofs are of a kind. */
214	export function proofsOf(c: Pick<Claim, 'proofs' | 'photoProofs'>, kind: string): number {
215	  const photos = c.photoProofs ?? 0;
216	  return kind === 'photo' ? photos : kind === 'receipt' ? (c.proofs ?? 0) - photos : 0;
217	}
218	
219	/** Raise a claim's proofs count by one, of the kind chosen ('': none, a receipt); refused (rejects) for a SETTLED or VOID claim, or one dated
220	 *  in a closed period. */
221	export function addProof(sheetId: string, by: string, id: number, kind: ProofKind | ''): Promise<Claim> {
222	  const ofKind = kind ? `&kind=${encodeURIComponent(kind)}` : '';
223	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/proofs?by=${encodeURIComponent(by)}${ofKind}`, {});
224	}
225	
226	/** Comment a claim, by the user on the sheet's today; refused (rejects) for an empty comment. */
227	export function commentClaim(sheetId: string, by: string, id: number, text: string): Promise<Claim> {
228	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/comments?by=${encodeURIComponent(by)}&text=${encodeURIComponent(text)}`, {});
229	}
230	
231	/** Add a line to a DRAFT claim (counts as editing it): its amount becomes its lines' quantities times
232	 *  unit amounts, added up. Refused (rejects) for a claim not a DRAFT, one due by a day in a closed period,
233	 *  one another user is editing, an empty label, a quantity not a whole number of at least 1, or a unit
234	 *  amount with more than two decimals. */
235	export function addClaimLine(sheetId: string, by: string, id: number, line: ClaimLineInput): Promise<Claim> {
236	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/lines?by=${encodeURIComponent(by)}&label=${encodeURIComponent(line.label)}`
237	    + `&qty=${encodeURIComponent(line.qty)}&unit=${encodeURIComponent(line.unit)}`, {});
238	}
239	
240	/** A line typed for a claim: its label, quantity and unit amount. */
241	export type ClaimLineInput = { label: string; qty: string; unit: string };
242	
243	/** A steward moves a DRAFT, OPEN or PENDING claim to another person (`toPersonId`): it keeps its
244	 *  number and date, loses any figure a statement bound it to, and is listed as that person's newest
245	 *  claim. Refused (rejects) for anyone else, for a SETTLED or VOID claim, or one due by a day in a closed period. */
246	export function reassignClaim(sheetId: string, by: string, id: number, toPersonId: number): Promise<Claim> {
247	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/reassign?by=${encodeURIComponent(by)}&to=${toPersonId}`, {});
248	}
249	
250	/** Share a claim with another person on the sheet at a percent (two decimals, more than 0.00); refused (rejects)
251	 *  for a SETTLED, VOID or DELETED claim, its own person, a person already holding a share of it, and shares
252	 *  adding up to more than 100.00. */
253	export function shareClaim(sheetId: string, by: string, id: number, withPersonId: number, share: string): Promise<Claim> {
254	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/share?by=${encodeURIComponent(by)}`
255	    + `&with=${withPersonId}&share=${encodeURIComponent(share)}`, {});
256	}
257	
258	/** A claim's holders as shown: `<name> <share>`, comma and space separated. */
259	export const showShares = (c: Claim) => (c.shares ?? []).map((s) => `${s.name} ${s.share}`).join(', ');
260	
261	/** Whether a claim counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED do. */
262	export const counts = (c: Claim) => isOpen(c) || c.status === 'SETTLED';
263	
264	/** The claims that count in live totals: all but the deferred claims and the open claims that no statement bound
265	 *  of a person whose retirement date the sheet's today has reached (`retiredReached`) (SETTLED and bound claims still
266	 *  count). A hold (the person's or the claim's own) leaves nothing out: it only matters in the pools. */
267	export function liveClaims(claims: Claim[], people: Array<{ id: number; retiredReached?: boolean }> | undefined): Claim[] {
268	  const byId = new Map((people ?? []).map((p) => [p.id, p]));
269	  return claims.filter((c) => !c.deferred && !(isOpen(c) && !c.stated && !!byId.get(c.personId)?.retiredReached));
270	}
271	
272	/** The claims that count in claimed and the claimed-total: as `liveClaims`. */
273	export const claimedClaims = liveClaims;
274	
275	/** Whether a person is active: one of their claims that count (`live`, see `liveClaims`) is open (OPEN or
276	 *  PENDING) and dated within the 30 days up to and including the sheet's `today`. */
277	export function isActive(live: Claim[], today: string): boolean {
278	  if (today === '') return false;
279	  const since = new Date(`${today}T00:00:00Z`);
280	  since.setUTCDate(since.getUTCDate() - 29);
281	  const from = since.toISOString().slice(0, 10);
282	  return live.some((c) => isOpen(c) && from <= c.date && c.date <= today);
283	}
