285	/** A person's patrons' shares (in hundredths, of 100.00), in the order named: 100.00 split equally, each share
286	 *  rounded half to even to two decimals, the remainder (100.00 less the shares added up) to the first-named. */
287	export function patronShares(patronIds: number[]): Array<{ id: number; share: number }> {
288	  const n = patronIds.length;
289	  if (n === 0) return [];
290	  const whole = Math.floor(10_000 / n);
291	  const rest = 10_000 % n;
292	  const each = 2 * rest > n || (2 * rest === n && whole % 2 === 1) ? whole + 1 : whole;
293	  return patronIds.map((id, i) => ({ id, share: i === 0 ? 10_000 - each * (n - 1) : each }));
294	}
