296	/** A person's backing: the sum over their patrons of the patron's figure (the frozen settled figures of their
297	 *  SETTLED claims dated within the 90 days up to and including the sheet's `today`, added up) times their share
298	 *  (see `patronShares`) divided by 100, rounded half to even (0.00 with none). */
299	export function backing(claims: Claim[], patronIds: number[], today: string): string {
300	  if (today === '') return '0.00';
301	  const since = new Date(`${today}T00:00:00Z`);
302	  since.setUTCDate(since.getUTCDate() - 89);
303	  const from = since.toISOString().slice(0, 10);
304	  const figures = new Map<number, bigint>(patronIds.map((id) => [id, 0n]));
305	  for (const c of claims) {
306	    const f = figures.get(c.personId);
307	    if (f !== undefined && c.status === 'SETTLED' && c.settledDue !== null && from <= c.date && c.date <= today) {
308	      figures.set(c.personId, f + BigInt(Math.round(Number(c.settledDue) * 100)));
309	    }
310	  }
311	  // Cents times hundredths of a percent share: 1/10_000 of a cent.
312	  const product = patronShares(patronIds).reduce((t, p) => t + (figures.get(p.id) ?? 0n) * BigInt(p.share), 0n);
313	  const cents = halfEven(product < 0n ? -product : product);
314	  const signed = product < 0n ? -cents : cents;
315	  return (Number(signed) / 100).toFixed(2);
316	}
