318	/** A non-negative amount in 1/10_000 of a cent to cents, half to even. */
319	function halfEven(product: bigint): bigint {
320	  const whole = product / 10_000n;
321	  const rest = product % 10_000n;
322	  return rest > 5_000n || (rest === 5_000n && whole % 2n === 1n) ? whole + 1n : whole;
323	}
