325	/** Sum the amounts of the claims that count (see `counts`) exactly (in cents), shown with two decimals. */
326	export function sumAmounts(claims: Claim[]): string {
327	  const cents = claims.filter(counts).reduce((t, c) => t + Math.round(Number(c.amount) * 100), 0);
328	  return (cents / 100).toFixed(2);
329	}
