6	/** A grade's rate on the sheet: a percent as two-decimal text, in force from its from-date
7	 *  (yyyy-MM-dd; null applies from the beginning of time) through its to-date (null: no end). A grade
8	 *  with no rate is not listed. Its level is how far up the sheet's parent chain it comes from (0: the
9	 *  sheet's own; 1: its parent's; up to 3). Its version is how many versions the grade's rate from that
10	 *  from-date has had: setting it again keeps the old value as an older version; this, the newest, is in force.
11	 *  A forward-only rate (saved with a from-date on or after the sheet's today) has `claimsAfter`, the highest
12	 *  claim id there was when it was saved: it applies only to claims with a higher id; those up to it go by
13	 *  `prior`, the version it replaced (null: none from its from-date). Without it, it applies to every claim. */
14	export type Rate = {
15	  sheetId: string; grade: string; pct: string; from: string | null; to: string | null; level: number; version: number;
16	  claimsAfter: number | null; prior: Rate | null;
17	};
18	
19	/** The version of a rate that applies to a claim (by its id): see `Rate`; undefined when none does. */
20	function forClaim(r: Rate, claimId: number): Rate | undefined {
21	  if (r.claimsAfter == null || claimId > r.claimsAfter) return r;
22	  return r.prior == null ? undefined : forClaim(r.prior, claimId);
23	}
24	/** A blank `from` sets the rate that applies from the beginning of time; a blank `to` has no end. */
25	export type RateInput = { grade: string; pct: string; from: string; to: string };
26	
27	const base = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
