37	/** Set a grade's rate from a from-date, as a new version of the one with the same grade and from-date;
38	 *  refused (rejects) when the percent is missing, negative or has more than two decimals, or the
39	 *  from-date or to-date is not a date, or the to-date is before the from-date. */
40	export function setRate(sheetId: string, by: string, input: RateInput): Promise<Rate> {
41	  return postJson<Rate>(`${base(sheetId)}?by=${encodeURIComponent(by)}`, input);
42	}
