44	/** Withdraw the newest version of the sheet's own rate for a grade from a from-date (null: from the beginning
45	 *  of time): the version before it applies again; with none the rate is gone. Refused (rejects) for anyone but
46	 *  a steward. */
47	export function withdrawRate(sheetId: string, by: string, grade: string, from: string | null): Promise<unknown> {
