54	/** Set a rate per line of grade,rate,from,to (the from-date and to-date may be absent or blank), in
55	 *  order, each as `setRate` sets it; refused (rejects) with nothing set when there is no line or any
56	 *  line would be refused by `setRate`. */
57	export function importRates(sheetId: string, by: string, text: string): Promise<ImportRatesResult> {
58	  return postJson<ImportRatesResult>(`/api/sheets/${encodeURIComponent(sheetId)}/import-rates?by=${encodeURIComponent(by)}`, { text });
