61	/** The grade's rate in force on a date (yyyy-MM-dd): the one with the latest from-date on or
62	 *  before it; at a level where the date is before every rate the grade has, or it has none, or
63	 *  that one ended (its to-date) before the date, the next level up is looked at; undefined (n/a)
64	 *  when no level has one. With a claim id, only the versions that apply to that claim are looked at
65	 *  (a forward-only rate saved after the claim was added does not). */
66	export function rateOn(rates: Rate[] | undefined, grade: string, date: string, claimId?: number): string | undefined {
67	  const levels = [...new Set((rates ?? []).map((r) => r.level ?? 0))].sort((a, b) => a - b);
68	  for (const level of levels) {
69	    let found: Rate | undefined;
70	    for (const listed of rates ?? []) {
71	      const r = claimId === undefined ? listed : forClaim(listed, claimId);
72	      if (r === undefined || (r.level ?? 0) !== level || r.grade !== grade || (r.from !== null && r.from > date)) continue;
73	      if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
74	    }
75	    if (found !== undefined && (found.to === null || found.to >= date)) return found.pct;
76	  }
77	  return undefined;
78	}
