80	/** The rate in force on a date for each grade that has one then. */
81	export function rateByGrade(rates: Rate[] | undefined, date: string): Map<string, string> {
82	  const byGrade = new Map<string, string>();
83	  for (const r of rates ?? []) {
84	    const pct = rateOn(rates, r.grade, date);
85	    if (pct !== undefined) byGrade.set(r.grade, pct);
86	  }
87	  return byGrade;
88	}
