90	/** Two-decimal text (may be negative) as a whole number of hundredths. */
91	export function hundredths(text: string): bigint {
92	  const t = text.trim();
93	  const negative = t.startsWith('-');
94	  const [whole, frac = ''] = (negative ? t.slice(1) : t).split('.');
95	  const value = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
96	  return negative ? -value : value;
97	}
