99	/** A claim's rate figure: an amount times a percent, divided by 100, rounded to two decimals (half up
100	 *  when `halfUp`, else half to even; no floor: that is applied by `claimDue`, before the late charge);
101	 *  null (n/a) when there is no rate. Exact: worked in whole hundredths. */
102	export function dueOf(amount: string, pct: string | undefined, halfUp: boolean): string | null {
103	  if (pct === undefined) return null;
104	  // amount (1/100) x pct (1/100) / 100 is in 1/1_000_000; to cents is / 10_000.
105	  return formatCents(roundPct(hundredths(amount) * hundredths(pct), halfUp));
106	}
