108	/** What a claim's late charge goes by: the sheet's late percent by date (a charge goes by the one in force on each 30-day boundary) and its today (a claim's due-by is its own);
109	 *  the sheet's policy date (its today when blank), which decides how a claim's live figures round; and the date
110	 *  a claim's lateness counts from (`lateFrom`: its due-by plus the grace days of its person's grade in force on
111	 *  its date, as in force on that date); and the rounding mode by date (half-up or half-even; '': none). */
112	export type Late = { pct: DatedOn; today: string; policy: string; lateFrom: (c: Claim) => string; rounding: DatedOn };
113	
114	/** Whether a claim's live figures round half up: by the rounding mode in force on its round date (its
115	 *  own, or for a correction the date of the claim it corrects); with none, when that date is before the
116	 *  policy date; else they round half to even. */
117	export const roundsHalfUp = (c: Claim, late: Late) => {
118	  const date = c.roundDate ?? c.date;
119	  const mode = late.rounding(date);
120	  return mode === 'half-up' ? true : mode === 'half-even' ? false : date < late.policy;
121	};
122	
123	/** The late charge on an open (OPEN or PENDING) claim's `figure`, compounding: for each full 30 days it is past its
124	 *  due-by plus its grace days (`late.lateFrom`) on the sheet's today, the late percent in force on that boundary date
125	 *  (that date plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries before it,
126	 *  each rounded by the policy date to two decimals, added up (0 when not overdue, on a correction, and once waived). */
127	export function lateCharge(c: Claim, figure: string, late: Late): bigint {
128	  const from = late.lateFrom(c);
129	  if (isCorrection(c) || c.waived || !isOverdue(c, late.today, from)) return 0n;
130	  const start = Date.parse(`${from}T00:00:00Z`);
131	  const periods = Math.floor((Date.parse(`${late.today}T00:00:00Z`) - start) / 86_400_000 / 30);
132	  let total = 0n;
133	  for (let k = 1; k <= periods; k++) {
134	    const boundary = new Date(start + k * 30 * 86_400_000).toISOString().slice(0, 10);
135	    total += roundPct((hundredths(figure) + total) * hundredths(late.pct(boundary)), roundsHalfUp(c, late));
136	  }
137	  return total;
138	}
