140	/** A person's grade in force on a date (yyyy-MM-dd). */
141	export type GradeOn = (date: string) => string;
142	
143	/** A claim's due: the one fixed when it was settled (its late charge then frozen in), else the one bound by its
144	 *  person's last statement (its due as shown then, late charge and floor included; n/a when it bound none), else
145	 *  live at the rate in force on the claim's date of the grade in force then (`gradeOn`), raised to at least the `floor`
146	 *  in force on its date (a correction, a negative amount, has no floor), with the late charge on that floored figure
147	 *  on the sheet's today on top. */
148	export function claimDue(c: Claim, rates: Rate[] | undefined, gradeOn: GradeOn, floor: DatedOn, late: Late): string | null {
149	  if (c.settledDue !== null) return c.settledDue;
150	  if (c.stated) return c.statedDue;
151	  const figure = dueOf(c.amount, rateOn(rates, gradeOn(c.date), c.date, c.id), roundsHalfUp(c, late));
152	  if (figure === null) return null;
153	  const least = hundredths(floor(c.date));
154	  const floored = !isCorrection(c) && hundredths(figure) < least ? least : hundredths(figure);
155	  return formatCents(floored + lateCharge(c, formatCents(floored), late));
156	}
