158	/** A product of hundredths and a percent's hundredths (in 1/1_000_000) to cents, half up (away
159	 *  from zero) when `halfUp`, else half to even (symmetric about zero). */
160	function roundPct(product: bigint, halfUp: boolean): bigint {
161	  return roundBy(product, 10_000n, halfUp);
162	}
163	
164	/** `value` divided by `by`, rounded half up (away from zero) when `halfUp`, else half to even (symmetric about zero). */
165	function roundBy(value: bigint, by: bigint, halfUp: boolean): bigint {
166	  if (value < 0n) return -roundBy(-value, by, halfUp);
167	  const whole = value / by;
168	  const rest = (value % by) * 2n;
169	  return rest > by || (rest === by && (halfUp || whole % 2n === 1n)) ? whole + 1n : whole;
170	}
