172	/** A holder's frozen part of a SETTLED claim's due: the due times their share divided by 100, rounded half to even. */
173	export function sharePart(due: string, share: string): string {
174	  return formatCents(roundPct(hundredths(due) * hundredths(share), false));
175	}
176	
177	/** A holder's part of a live claim: its amount times their share divided by 100, times the rate of the holder's own
178	 *  grade in force on the claim's date (`pct`) divided by 100, rounded like the claim (half up when `halfUp`, else half
179	 *  to even); 0.00 when their grade has no rate. Exact: worked in whole hundredths. */
180	export function holderPart(amount: string, share: string, pct: string | undefined, halfUp: boolean): string {
181	  if (pct === undefined) return '0.00';
182	  // amount (1/100) x share (1/100) x pct (1/100) / 10_000 is in 1/100_000_000 of a cent's worth; to cents is / 100_000_000.
183	  return formatCents(roundBy(hundredths(amount) * hundredths(share) * hundredths(pct), 100_000_000n, halfUp));
184	}
