186	/** The rate of a holder's own grade in force on a live claim's date (undefined: none; see `holderPart`). */
187	export type HolderPct = (c: Claim, s: ClaimShare) => string | undefined;
188	
189	/** A part of a claim a person holds of another's claim (see `Claim.shares`), or, `given`, the part (negative) a
190	 *  holder takes of the person's own claim. */
191	export type HeldPart = { claim: Claim; part: string; given?: boolean };
192	
193	/** The parts a person (`personId`) holds of the claims among `claims` (the live ones) that count, and (`given`,
194	 *  negative) the parts others hold of theirs: a SETTLED claim's frozen with its due (`dueOfClaim`, n/a ones skipped),
195	 *  a live one's by the holder's own grade's rate (`holderPct`; one whose grade has none holds nothing). A claim
196	 *  whose due is n/a gives nothing away from its own person. */
197	export function heldParts(personId: number, claims: Claim[], dueOfClaim: (c: Claim) => string | null,
198	  holderPct: HolderPct, late: Late): HeldPart[] {
199	  const partOf = (c: Claim, s: ClaimShare): string | null => {
200	    if (c.settledDue !== null) return sharePart(c.settledDue, s.share);
201	    const pct = holderPct(c, s);
202	    return pct === undefined ? null : holderPart(c.amount, s.share, pct, roundsHalfUp(c, late));
203	  };
204	  const held: HeldPart[] = [];
205	  for (const c of claims) {
206	    if (!counts(c)) continue;
207	    if (c.personId === personId) {
208	      if ((c.shares ?? []).length === 0 || dueOfClaim(c) === null) continue;
209	      for (const s of c.shares ?? []) {
210	        const part = partOf(c, s);
211	        if (part !== null) held.push({ claim: c, part: formatCents(-hundredths(part)), given: true });
212	      }
213	      continue;
214	    }
215	    const share = (c.shares ?? []).find((s) => s.personId === personId);
216	    const part = share === undefined ? null : partOf(c, share);
217	    if (part !== null) held.push({ claim: c, part });
218	  }
219	  return held;
220	}
