222	/** A person's due-total: the sum of their counting claims' due figures (n/a ones skipped; a shared one less its
223	 *  holders' parts, given in `held`) and the parts they hold of others' (`held`, see `heldParts`), at most `cap` (the sheet's cap less the person's cut total, see `capLessCuts`; null: no cap); n/a
224	 *  when their grade today has no rate today (`pct`), they hold no part of another's claim, and none of those claims keeps a settled or bound
225	 *  figure, or a live one at a grade no longer in force on the sheet's today or dated on or before it
226	 *  (its rate since ended). */
227	export function personDue(claims: Claim[], rates: Rate[] | undefined, gradeOn: GradeOn, pct: string | undefined,
228	  floor: DatedOn, late: Late, cap: string | null, held: HeldPart[] = []) {
229	  const own = claims.filter(counts);
230	  const now = gradeOn(late.today);
231	  const kept = (c: Claim) => c.settledDue !== null || isBound(c)
232	    || ((gradeOn(c.date) !== now || c.date <= late.today) && rateOn(rates, gradeOn(c.date), c.date, c.id) !== undefined);
233	  if (pct === undefined && !own.some(kept) && !held.some((h) => !h.given)) return null;
234	  const sum = sumDues([...own.map((c) => claimDue(c, rates, gradeOn, floor, late)), ...held.map((h) => h.part)]);
235	  return cap !== null && hundredths(sum) > hundredths(cap) ? formatCents(hundredths(cap)) : sum;
236	}
