238	/** What a person's due figures add up to above their `cap` (the sheet's cap less their cut total; null: no cap); 0.00 when they do
239	 *  not exceed it, or their due-total is n/a. */
240	export function excessOf(claims: Claim[], rates: Rate[] | undefined, gradeOn: GradeOn, pct: string | undefined,
241	  floor: DatedOn, late: Late, cap: string | null, held: HeldPart[] = []): string {
242	  const full = personDue(claims, rates, gradeOn, pct, floor, late, null, held);
243	  return full === null || cap === null || hundredths(full) <= hundredths(cap) ? '0.00'
244	    : formatCents(hundredths(full) - hundredths(cap));
245	}
