247	/** A person's due split by status among their claims that count (`claims`, the live ones): settled (their SETTLED
248	 *  claims, at their frozen figures, corrections included) and open (their OPEN and PENDING ones); n/a ones skipped;
249	 *  a shared claim less its holders' parts, and the parts they hold of others' (both in `held`, see `heldParts`) by those claims' status.
250	 *  The two add up to their due-total before the cap. */
251	export function splitDues(claims: Claim[], dueOfClaim: (c: Claim) => string | null, held: HeldPart[] = []) {
252	  const own = dueOfClaim;
253	  return {
254	    settled: sumDues([...claims.filter((c) => c.status === 'SETTLED').map(own),
255	      ...held.filter((h) => h.claim.status === 'SETTLED').map((h) => h.part)]),
256	    open: sumDues([...claims.filter(isOpen).map(own), ...held.filter((h) => isOpen(h.claim)).map((h) => h.part)]),
257	  };
258	}
259	
260	/** The overdue claims among those that count (`claims`, the live ones) on the sheet's today (`charges.today`,
261	 *  each past its `charges.lateFrom`): their count and the sum of their due figures (n/a ones skipped). */
262	export function overdue(claims: Claim[], charges: Late, dueOfClaim: (c: Claim) => string | null) {
263	  const late = claims.filter((c) => isOverdue(c, charges.today, charges.lateFrom(c)));
264	  return { count: late.length, total: sumDues(late.map(dueOfClaim)) };
265	}
266	
267	/** A person's score: their settled figures (`settled`, see `splitDues`, corrections left out) divided by 100, less 5 for each of
268	 *  their overdue claims (`overdueCount`, see `overdue`), rounded half to even to a whole number. */
269	export function personScore(settled: string, overdueCount: number): string {
270	  const scaled = hundredths(settled) - BigInt(overdueCount) * 50_000n; // in 1/10_000 of a point
271	  const negative = scaled < 0n;
272	  const abs = negative ? -scaled : scaled;
273	  let whole = abs / 10_000n;
274	  const rest = abs % 10_000n;
275	  if (rest > 5_000n || (rest === 5_000n && whole % 2n === 1n)) whole += 1n;
276	  return negative && whole !== 0n ? `-${whole}` : `${whole}`;
277	}
278	
279	/** The due of the open (OPEN or PENDING) claims among those that count (`claims`, the live ones), split by
280	 *  their age on the sheet's `today` (the days from the claim's date): 0 to 30, 31 to 60, and 61 or more
281	 *  (one dated after today is 0 to 30); n/a ones skipped. */
282	export function agedDues(claims: Claim[], today: string, dueOfClaim: (c: Claim) => string | null) {
283	  const buckets: Array<Array<string | null>> = [[], [], []];
284	  const now = Date.parse(`${today}T00:00:00Z`);
285	  for (const c of claims.filter(isOpen)) {
286	    const age = today === '' ? 0 : Math.round((now - Date.parse(`${c.date}T00:00:00Z`)) / 86_400_000);
287	    buckets[age <= 30 ? 0 : age <= 60 ? 1 : 2].push(dueOfClaim(c));
288	  }
289	  return { upTo30: sumDues(buckets[0]), upTo60: sumDues(buckets[1]), over60: sumDues(buckets[2]) };
290	}
291	
292	/** Add up two-decimal dues, skipping n/a. */
293	export function sumDues(dues: Array<string | null>): string {
294	  return formatCents(dues.reduce<bigint>((t, d) => (d === null ? t : t + hundredths(d)), 0n));
295	}
296	
297	/** A sheet total of per-person figures: added up (n/a ones are no figure), leaving out the single
298	 *  highest and the single lowest figure when there are three or more. */
299	export function trimmedSum(figures: Array<string | null>): string {
300	  const cents = figures.filter((f): f is string => f !== null).map(hundredths).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
301	  const kept = cents.length >= 3 ? cents.slice(1, -1) : cents;
302	  return formatCents(kept.reduce((t, c) => t + c, 0n));
303	}
304	
305	export function formatCents(cents: bigint): string {
306	  const abs = cents < 0n ? -cents : cents;
307	  const frac = (abs % 100n).toString().padStart(2, '0');
308	  return `${cents < 0n ? '-' : ''}${abs / 100n}.${frac}`;
309	}
