314	/** What a candidate rate for a grade on every date would change: how many open (OPEN or PENDING) claims
315	 *  of people on that grade on the claim's date would show a different due, and the sum of the differences
316	 *  (new minus current, two decimals). */
317	export type RatePreview = { count: number; diff: string };
