319	/** Preview a candidate rate for a grade; nothing is saved. Refused (rejects) when the percent is missing,
320	 *  negative or has more than two decimals. */
321	export function previewRate(sheetId: string, grade: string, pct: string): Promise<RatePreview> {
322	  return getJson<RatePreview>(`/api/sheets/${encodeURIComponent(sheetId)}/rate-preview`
323	    + `?grade=${encodeURIComponent(grade)}&pct=${encodeURIComponent(pct)}`);
324	}
