978	/** Who has a row on the people list for the user: everyone, unless their role is restricted; then only
979	 *  the person whose name or an alias is the user's name (as names are compared) and the people (lead
980	 *  and members) of the crews that person leads or belongs to. Undefined while anything it needs is loading. */
981	function visibleTo(user: string, role: string | undefined, people: Person[] | undefined,
982	    crews: Crew[] | undefined): ((p: Person) => boolean) | undefined {
983	  if (role === undefined) return undefined;
984	  if (role !== 'restricted') return () => true;
985	  if (people === undefined || crews === undefined) return undefined;
986	  const me = user.trim().toLowerCase();
987	  const self = people.find((q) => [q.name, ...q.aliases].some((n) => n.trim().toLowerCase() === me));
988	  if (!self) return () => false;
989	  const ids = new Set<number>([self.id]);
990	  for (const c of crews) {
991	    const members = c.members.map((m) => m.personId);
992	    if (c.leadId === self.id || members.includes(self.id)) {
993	      if (c.leadId !== null) ids.add(c.leadId);
994	      members.forEach((id) => ids.add(id));
995	    }
996	  }
997	  return (p) => ids.has(p.id);
998	}
