128	    32	        DatedSetting floor = settings.floor(id);
129	    33	        Dues.Late late = settings.late(id, sheets.today(id));
130	    34	        String pct = candidate.pct().toPlainString();
131	    35	        int count = 0;
132	    36	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
133	    37	        for (Claim c : claims.list(id)) {
134	    38	            if (!ClaimStatus.isOpen(c.getStatus())) continue;
135	    39	            Person p = byId.get(c.getPersonId());
136	    40	            if (p == null || !candidate.grade().equals(p.gradeOn(c.getDate()))) continue;
137	    41	            Rate rate = RateRepository.inForce(sheetRates, candidate.grade(), c.getDate(), c.getId());
138	    42	            String now = Dues.shown(c, rate == null ? null
139	    43	                    : Dues.of(c.getAmount(), rate.pct(), late.rounding(c.getRoundDate())), floor.on(c.getDate()), late);
140	    44	            String then = Dues.shown(c, Dues.of(c.getAmount(), pct, late.rounding(c.getRoundDate())),
141	    45	                    floor.on(c.getDate()), late);
