78	/** The person's grade in force on a date (yyyy-MM-dd): the one with the latest from-date on or before it. */
79	export function gradeOn(p: Person, date: string): string {
80	  let found: GradeFrom | undefined;
81	  for (const g of p.grades) {
82	    if (g.from !== null && g.from > date) continue;
83	    if (found === undefined || (found.from ?? '') < (g.from ?? '')) found = g;
84	  }
