88	/** The person's timeline: one line per dated thing about them (`<date> grade <grade>` for each dated
89	 *  grade, `<date> claim <amount> <status>` for each of their `claims`, `<date> hold [to <date>]` for each
90	 *  hold, `<date> retired` for each retirement past or present, `<date> unretired` for each past one),
91	 *  by date, a date's grades then claims (by their line's text) then holds then retirements then unretirements. */
92	export function timeline(p: Person, claims: Claim[]): string[] {
93	  const lines: { date: string; kind: number; order: number | string; text: string }[] = [];
94	  p.grades.forEach((g, i) => {
95	    if (g.from !== null) lines.push({ date: g.from, kind: 0, order: i, text: `grade ${g.grade}` });
96	  });
97	  claims.forEach((c) => lines.push({ date: c.date, kind: 1, order: `claim ${c.amount} ${c.status}`, text: `claim ${c.amount} ${c.status}` }));
98	  p.holds.forEach((h, i) => lines.push({ date: h.from, kind: 2, order: i, text: h.to === null ? 'hold' : `hold to ${h.to}` }));
99	  p.retirements.forEach((r, i) => {
100	    lines.push({ date: r.from, kind: 3, order: i, text: 'retired' });
101	    lines.push({ date: r.to, kind: 4, order: i, text: 'unretired' });
102	  });
103	  if (p.retiredFrom !== null) lines.push({ date: p.retiredFrom, kind: 3, order: p.retirements.length, text: 'retired' });
104	  lines.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : a.kind - b.kind || (a.order < b.order ? -1 : a.order > b.order ? 1 : 0)));
105	  return lines.map((l) => `${l.date} ${l.text}`);
106	}
