101	export function settingOn(settings: Setting[] | undefined, key: string, date: string): string | undefined {
102	  let found: Setting | undefined;
103	  for (const s of settings ?? []) {
104	    if (s.key !== key || (s.from !== null && s.from > date)) continue;
105	    if (found === undefined || (found.from ?? '') < (s.from ?? '')) found = s;
106	  }
