256	 *  number of versions whose from-date is on or before it (one with no from-date counts always). */
257	export function usePolicyVersions(sheetId: string): { current: number; on: (date: string) => number } {
258	  const versions = useQuery({ queryKey: policyVersionsKey(sheetId), queryFn: () => listPolicyVersions(sheetId) });
259	  const all = versions.data ?? [];
