266	/** What a claim's late charge and rounding go by: the sheet's late percent by date (a late charge goes
267	 *  by the one in force on each 30-day boundary), today and policy date (its today when blank), and the
268	 *  date a claim's lateness counts from: its due-by plus the grace days (grace-<grade>) of its person's
269	 *  grade in force on its date, as in force on that date (blank: none). */
270	export function useLate(sheetId: string, today: string, live = false): Late {
271	  const settings = useQuery({ queryKey: liveKey(settingsKey(sheetId), live), queryFn: () => listSettings(sheetId, live) });
272	  const people = useQuery({ queryKey: liveKey(peopleKey(sheetId), live), queryFn: () => listPeople(sheetId, live) });
273	  const pct = (date: string) => settingOn(settings.data, 'late-pct', date) || SETTING_DEFAULTS['late-pct'];
274	  const policy = settingOn(settings.data, 'policy-date', today) || today;
275	  const lateFrom = (c: Claim) => {
276	    const person = people.data?.find((p) => p.id === c.personId);
277	    const grace = person === undefined ? '' : settingOn(settings.data, `grace-${gradeOn(person, c.date)}`, c.date) ?? '';
278	    if (grace === '') return dueBy(c);
279	    const from = new Date(Date.parse(`${dueBy(c)}T00:00:00Z`) + Number(grace) * 86_400_000);
280	    return from.toISOString().slice(0, 10);
281	  };
282	  const rounding = (date: string) => settingOn(settings.data, 'rounding', date) ?? '';
283	  return { pct, today, policy, lateFrom, rounding };
284	}
