    22	
    23	/** For every plan on the sheet, in the order they were added, adds a DRAFT claim of the plan's amount,
    24	 *  dated that day with an empty note, for every plan date (the start, then every N days; or the day of the month in every month) up to the end
    25	 *  and the sheet's today that the plan has made none for yet. Each is checked as
    26	 *  {@link net.officefloor.hq.app.claim.AddClaim} checks a claim (its person not retired before its date,
    27	 *  its due-by outside a closed period): a date that is refused is skipped, to be tried again next time.
    28	 *  Each claim made is logged and recorded as CLAIM_ADDED. A plan naming a descendant sheet makes its claims
    29	 *  on that sheet, for the person of the same name there (none when there is none), by that sheet's rules and
    30	 *  recorded in its audit. Refused on an archived sheet; a viewer may
    31	 *  make none: for a viewer nothing is written and none are counted. */
    32	public class GeneratePlanClaims {
    33	    public void generate(@PathVariable("sheetId") String sheetId,
    34	            @RequestParam(name = "by", required = false) String by, PlanRepository plans,
    35	            PersonRepository people, SheetRepository sheets, ClaimRepository claims, PeriodRepository periods,
    36	            SettingRepository settings, HolidayRepository holidays, ClaimLogRepository log, Audit audit,
    37	            RoleRepository roles, Out<GenerateResult> result) throws SheetArchivedException {
    38	        String id = sheetId.trim();
    39	        String user = by == null ? "" : by;
    40	        if (sheets.isArchived(id)) {
    41	            throw new SheetArchivedException("The sheet is archived");
    42	        }
    43	        if (Role.VIEWER.equals(roles.roleOf(id, user))) {
    44	            result.set(new GenerateResult(0));
    45	            return;
    46	        }
    47	        LocalDate today = sheets.today(id);
    48	        int made = 0;
    49	        for (Plan plan : plans.list(id)) {
    50	            Person person = people.find(id, plan.personId());
    51	            if (person == null) continue;
    52	            // A plan naming a descendant sheet makes its claims there, for the person of the same name.
    53	            String on = plan.targetSheet() == null ? id : plan.targetSheet();
    54	            if (!on.equals(id)) {
    55	                if (sheets.isArchived(on)) continue;
    56	                person = people.findByName(on, person.getName());
    57	                if (person == null) continue;
    58	            }
    59	            Set<LocalDate> done = plans.made(plan.id());
    60	            LocalDate last = plan.end().isBefore(today) ? plan.end() : today;
    61	            for (LocalDate date : plan.dates(last)) {
    62	                if (done.contains(date) || person.retiredBefore(date)) continue;
    63	                // The due-by is fixed now, as for a claim added on the form.
    64	                LocalDate dueBy = holidays.dueBy(on, date, settings.termsToday(on, person));
    65	                try {
    66	                    periods.requireOpen(on, dueBy.toString());
    67	                } catch (PeriodClosedException e) {
    68	                    continue;
    69	                }
    70	                Claim claim = claims.add(on, person.getId(), plan.amount(), date, "", null, dueBy, user);
    71	                if (periods.softClosedOn(on, dueBy.toString())) claims.markLateEntry(claim);
    72	                plans.recordMade(plan.id(), date, claim.getId());
    73	                log.record(claim, user);
    74	                audit.record("CLAIM_ADDED sheet=" + on + " by=" + user + " person=" + person.getName()
    75	                        + " amount=" + claim.getAmount() + " date=" + claim.getDate() + claim.getAuditRef());
    76	                if (claim.isLateEntry()) {
    77	                    audit.record("LATE_ENTRY sheet=" + on + " by=" + user + " person=" + person.getName()
    78	                            + " amount=" + claim.getAmount() + " date=" + claim.getDate());
    79	                }
    80	                made++;
    81	            }
    82	        }
    83	        result.set(new GenerateResult(made));
    84	    }
    85	}
