    22	
    23	/** Merges a grade into another: recorded as GRADE_MERGED, then everyone whose grade in force on the
    24	 *  sheet's today is the merged grade is given the other from the sheet's today, in list order, each
    25	 *  as the person form would (its PERSON_EDITED line, then the rollup lines it moved); then the rollup
    26	 *  lines of what moved over the whole merge, once every grade record of theirs on the merged grade
    27	 *  has become the other (retroactive). Refused, with
    28	 *  nothing written, for anyone but a steward, on an archived sheet, or into a retired grade when
    29	 *  anyone would be given it. */
    30	public class MergeGrade {
    31	    public void merge(@PathVariable("sheetId") String sheetId,
    32	            @RequestParam(name = "by", required = false) String by, @Val MergeGradeRequest request,
    33	            PersonRepository people, ClaimRepository claims, RateRepository rates,
    34	            SheetRepository sheets, SettingRepository settings, PoolRepository pools,
    35	            RoleRepository roles, GradeRepository grades, Audit audit, Out<GradeMerged> result)
    36	            throws InvalidGradeException, SheetArchivedException, PersonConflictException {
    37	        String id = sheetId.trim();
    38	        String user = by == null ? "" : by;
    39	        if (!Role.STEWARD.equals(roles.roleOf(id, user))) {
    40	            throw new InvalidGradeException("Only a steward can merge a grade");
    41	        }
    42	        if (sheets.isArchived(id)) {
    43	            throw new SheetArchivedException("The sheet is archived");
    44	        }
    45	        java.util.List<Person> merged = people.list(id).stream()
    46	                .filter((p) -> request.from().equals(p.getGrade())).toList();
    47	        if (!merged.isEmpty()) {
    48	            try {
    49	                grades.requireChoosable(id, request.into());
    50	            } catch (InvalidPersonException e) {
    51	                throw new InvalidGradeException(e.getMessage());
    52	            }
    53	        }
    54	        audit.record("GRADE_MERGED sheet=" + id + " by=" + user + " from=" + request.from()
    55	                + " into=" + request.into());
    56	        LocalDate today = sheets.today(id);
    57	        Rollup start = Rollup.of(id, people, claims, rates, sheets, settings, pools);
    58	        Rollup before = start;
    59	        int count = 0;
    60	        for (Person listed : merged) {
    61	            Person person = people.find(id, listed.getId());
    62	            person.giveGrade(request.into(), today.toString(), today);
    63	            if (!people.update(person)) {
    64	                throw new PersonConflictException(person.getId());
    65	            }
    66	            if (person.getRecorded() != null) {
    67	                people.saveGrade(person, person.getRecorded(), user);
    68	            }
    69	            count++;
    70	            audit.record("PERSON_EDITED sheet=" + id + " by=" + user + " name=" + person.getName()
    71	                    + " grade=" + person.getGrade());
    72	            Rollup after = Rollup.of(id, people, claims, rates, sheets, settings, pools);
    73	            for (String line : after.changesSince(before, id, user)) {
    74	                audit.record(line);
    75	            }
    76	            before = after;
    77	        }
    78	        // The merge is retroactive: every grade record of theirs on the merged grade becomes the
    79	        // other, so all their claims, whatever their date, use the other grade.
    80	        for (Person listed : merged) {
    81	            people.regrade(people.find(id, listed.getId()), request.from(), request.into(), user);
    82	        }
    83	        before = Rollup.of(id, people, claims, rates, sheets, settings, pools);
    84	        // Then the merge's own rollup lines: what moved over the whole merge.
    85	        for (String line : before.changesSince(start, id, user)) {
    86	            audit.record(line);
    87	        }
    88	        result.set(new GradeMerged(count));
    89	    }
    90	}
