     1	package net.officefloor.hq.app.holiday;
     2	
     3	import java.time.DayOfWeek;
     4	import java.time.LocalDate;
     5	import java.util.Set;
     6	
     7	/** Terms count business days: every day but a Saturday, a Sunday and a holiday on the sheet. */
     8	public final class BusinessDays {
     9	
    10	    private BusinessDays() {
    11	    }
    12	
    13	    public static boolean isBusinessDay(LocalDate day, Set<LocalDate> holidays) {
    14	        DayOfWeek dow = day.getDayOfWeek();
    15	        return dow != DayOfWeek.SATURDAY && dow != DayOfWeek.SUNDAY && !holidays.contains(day);
    16	    }
    17	
    18	    /** A claim's due-by: the {@code terms}-th business day after its date, counting forward from the
    19	     *  day after it (terms 0: the date itself). */
    20	    public static LocalDate dueBy(LocalDate date, int terms, Set<LocalDate> holidays) {
    21	        LocalDate due = date;
    22	        for (int left = terms; left > 0; ) {
    23	            due = due.plusDays(1);
    24	            if (isBusinessDay(due, holidays)) left--;
    25	        }
    26	        return due;
    27	    }
    28	
    29	    /** The terms a due-by was fixed with: the business days after {@code date} up to and including
    30	     *  {@code dueBy} (none when it is not after the date). */
    31	    public static int between(LocalDate date, LocalDate dueBy, Set<LocalDate> holidays) {
