    59	
    60	    public void paste(@PathVariable("sheetId") String sheetId,
    61	            @RequestParam(name = "by", required = false) String by, @Val PasteLines lines,
    62	            PersonRepository people, SheetRepository sheets, ClaimRepository claims,
    63	            PeriodRepository periods, SettingRepository settings, PoolRepository pools, ClaimLogRepository log, Audit audit,
    64	            HolidayRepository holidays, RoleRepository roles, RateRepository rates, ClaimLineRepository claimLines,
    65	            Out<PasteResult> result, PlatformTransactionManager transactions)
    66	            throws PeriodClosedException, InvalidClaimException, ClaimStatusException, ClaimLockedException {
    67	        // Run in a transaction of its own: a line refused after earlier lines were written undoes them all.
    68	        TransactionStatus tx = transactions.getTransaction(new DefaultTransactionDefinition());
    69	        try {
    70	            pasteAll(sheetId, by, lines, people, sheets, claims, periods, settings, pools, log, audit, holidays, roles, rates,
    71	                    claimLines, result);
    72	        } catch (Throwable e) {
    73	            transactions.rollback(tx);
    74	            throw e;
    75	        }
    76	        transactions.commit(tx);
    77	    }
    78	
    79	    private void pasteAll(String sheetId,
    80	            String by, PasteLines lines,
    81	            PersonRepository people, SheetRepository sheets, ClaimRepository claims,
    82	            PeriodRepository periods, SettingRepository settings, PoolRepository pools, ClaimLogRepository log, Audit audit,
    83	            HolidayRepository holidays, RoleRepository roles, RateRepository rates, ClaimLineRepository claimLines,
    84	            Out<PasteResult> result)
    85	            throws PeriodClosedException, InvalidClaimException, ClaimStatusException, ClaimLockedException {
    86	        String id = sheetId.trim();
    87	        String user = by == null ? "" : by;
    88	        if (!Permissions.allows(id, user, Permissions.OPEN, roles, settings)) {
    89	            throw new ClaimStatusException("Your role may not open a claim");
    90	        }
    91	        List<Pending> pending = new ArrayList<>();
    92	        Set<String> refs = new HashSet<>();
    93	        Integer maxOpen = settings.maxOpen(id);
    94	        Map<Long, Long> opening = new HashMap<>();
    95	        for (PasteLine line : lines.lines()) {
    96	            Person person = people.findByName(id, line.name());
    97	            if (person == null) {
    98	                throw new InvalidClaimException("Not on the sheet: " + line.name());
    99	            }
   100	            // The maximum of open claims is checked before anything is written: each line opens one more.
   101	            if (maxOpen != null) {
   102	                long held = opening.computeIfAbsent(person.getId(), (p) -> claims.listOf(id, p).stream()
   103	                        .filter((c) -> ClaimStatus.isOpen(c.getStatus())).count());
   104	                if (held >= maxOpen) {
   105	                    throw new ClaimStatusException("The person already has " + maxOpen + " open claims");
   106	                }
   107	                opening.put(person.getId(), held + 1);
   108	            }
   109	            ValidClaim request = line.claim();
   110	            LocalDate date = request.date() != null ? request.date() : settings.entryDate(id);
   111	            Claim match = match(claims.listOf(id, person.getId()), date, request.note());
   112	            if (match != null) {
   113	                pending.add(new Pending(person, request, date, null, null, match));
   114	                continue;
   115	            }
   116	            if (person.retiredBefore(date)) {
   117	                throw new InvalidClaimException("The person is retired from " + person.getRetiredFrom());
   118	            }
   119	            // The due-by is fixed now, by the terms in force on the sheet's today,
   120	            // counted in business days past the weekends and the sheet's holidays as they are now.
   121	            LocalDate dueBy = holidays.dueBy(id, date, settings.termsToday(id, person));
   122	            periods.requireOpen(id, dueBy.toString());
   123	            String corrects = Corrections.check(request, id, person.getId(), claims);
   124	            // A reference is used once on the sheet: also once within the paste.
   125	            claims.requireRefFree(id, request.ref(), 0);
   126	            if (request.ref() != null && !refs.add(request.ref().toLowerCase(Locale.ROOT))) {
   127	                throw new InvalidClaimException("The reference is repeated in the paste: " + request.ref());
   128	            }
   129	            pending.add(new Pending(person, request, date, dueBy, corrects, null));
   130	        }
   131	
   132	        List<String> records = new ArrayList<>();
   133	        Rollup before = Rollup.of(id, people, claims, rates, sheets, settings, pools);
   134	        for (Pending p : pending) {
   135	            String head = " sheet=" + id + " by=" + user + " person=" + p.person().getName();
   136	            Claim claim;
   137	            if (p.match() != null) {
   138	                claim = claims.find(id, p.match().getId());
   139	                // An earlier line of the paste may have opened it already.
   140	                if (!ClaimStatus.DRAFT.name().equals(claim.getStatus())) {
   141	                    throw new InvalidClaimException("No DRAFT claim of " + p.person().getName() + " matches the line");
   142	                }
   143	                if (claim.getLockedBy() != null && !claim.getLockedBy().equals(user)) {
   144	                    throw new ClaimLockedException("The claim is being edited by " + claim.getLockedBy());
   145	                }
   146	                BigDecimal amount = p.claim().amount();
   147	                if (new BigDecimal(claim.getAmount()).compareTo(amount) != 0) {
   148	                    BigDecimal lined = claimLines.total(claim);
   149	                    if (lined != null && lined.compareTo(amount) != 0) {
   150	                        throw new InvalidClaimException("A claim with lines has their total as its amount: "
   151	                                + lined.toPlainString());
   152	                    }
   153	                    periods.requireOpen(id, claim.getDueBy());
   154	                    claim.setAmount(amount.toPlainString());
   155	                    claim.setEditedBy(user);
   156	                    claims.update(claim);
   157	                    records.add("CLAIM_EDITED" + head + " amount=" + claim.getAmount() + " date=" + claim.getDate()
   158	                            + claim.getAuditNumber());
   159	                }
   160	            } else {
   161	                claim = claims.add(id, p.person().getId(), p.claim().amount(), p.date(),
   162	                        p.claim().note(), p.corrects(), p.dueBy(), user, p.claim().ref());
   163	                if (periods.softClosedOn(id, claim.getDueBy())) claims.markLateEntry(claim);
   164	                log.record(claim, user);
   165	                records.add("CLAIM_ADDED" + head + " amount=" + claim.getAmount() + " date=" + claim.getDate()
   166	                        + claim.getAuditRef());
   167	                if (claim.isLateEntry()) {
   168	                    records.add("LATE_ENTRY" + head + " amount=" + claim.getAmount() + " date=" + claim.getDate());
   169	                }
   170	            }
   171	
   172	            // Opened as the open button opens it.
   173	            OpenChecks.requireFlagSteward(claim, user, people, roles);
   174	            periods.requireOpen(id, claim.getDueBy());
   175	            ClaimStatus opened = OpenChecks.opensTo(claim, people, rates, settings, sheets);
   176	            OpenChecks.requireNote(claim, people, rates, settings, sheets);
   177	            OpenChecks.requireUnderCap(claim, claims, periods);
   178	            OpenChecks.requireUnderMaxOpen(claim, claims, settings);
   179	            claim.setStatus(opened.name());
   180	            claim.setOpenedBy(user);
   181	            claims.update(claim);
   182	            log.record(claim, user);
   183	            records.add(opened.event() + head + " amount=" + claim.getAmount() + " date=" + claim.getDate()
   184	                    + claim.getAuditNumber());
   185	            Rollup after = Rollup.of(id, people, claims, rates, sheets, settings, pools);
   186	            records.addAll(after.changesSince(before, id, user));
   187	            before = after;
   188	        }
   189	        // Every line went through: only now is anything recorded.
   190	        for (String record : records) {
   191	            audit.record(record);
   192	        }
   193	        result.set(new PasteResult(pending.size()));
   194	    }
