   196	    /** The newest DRAFT of the person's claims (newest first) on the date with the note (blank: none);
   197	     *  null when none of them matches; refused when they match only claims that are not DRAFT. */
   198	    private static Claim match(List<Claim> theirs, LocalDate date, String note) throws InvalidClaimException {
   199	        String wanted = note == null ? "" : note.trim();
   200	        boolean matched = false;
   201	        for (Claim c : theirs) {
   202	            if (ClaimStatus.VOID.name().equals(c.getStatus()) || ClaimStatus.DELETED.name().equals(c.getStatus())) {
   203	                continue;
   204	            }
   205	            String has = c.getNote() == null ? "" : c.getNote().trim();
   206	            if (!date.toString().equals(c.getDate()) || !wanted.equals(has)) continue;
   207	            if (ClaimStatus.DRAFT.name().equals(c.getStatus())) return c;
   208	            matched = true;
   209	        }
   210	        if (matched) {
   211	            throw new InvalidClaimException("The line matches a claim that is no longer a DRAFT");
   212	        }
   213	        return null;
   214	    }
   215	}
