 33	/** Every query about a sheet lives under this key, so loading it again re-reads all of it. */
 34	export const sheetKey = (id: string) => ['sheet', id] as const;
 35	
 36	/** A query key about a sheet, for its live reads (`live`: as it is now, even while the screen shows it
 37	 *  as of a date) kept apart from the screen's; still under the sheet's key, so loading it re-reads them. */
 38	export const liveKey = <K extends readonly unknown[]>(key: K, live: boolean): readonly unknown[] =>
 39	  live ? [key[0], key[1], 'live', ...key.slice(2)] : key;
