 41	/** The loaded sheet's today, read from the sheet query `ActiveSheet` keeps; '' until loaded. */
 42	export function useSheetToday(id: string, by: string, live = false): string {
 43	  const sheet = useQuery({ queryKey: liveKey(sheetKey(id), live), queryFn: () => openSheet(id, by, live) });
 44	  return sheet.data?.today ?? '';
 45	}
