421	/** Shows a figure (an amount, due figure, total, rate, share or cut) in the signed-in user's locale.
422	 *  Wrap the content of every element that shows one; text that is not a figure is shown as it is. */
423	export function Fig({ children }: { children: ReactNode }) {
424	  const locale = useLocale();
425	  if (typeof children === 'string') return <>{formatFigure(children, locale)}</>;
426	  if (typeof children === 'number') return <>{formatFigure(String(children), locale)}</>;
427	  return <>{children}</>;
