429	import { useQuery } from '@tanstack/react-query';
430	import { getJson, putJson } from '../../api/http';
431	import { useUser } from './session';
432	
433	/** How the screen shows a user figures: en `1234.56`, de `1.234,56`. Saved per user. */
434	export const LOCALES = ['en', 'de'] as const;
435	export type Locale = (typeof LOCALES)[number];
436	export type UserLocale = { user: string; locale: Locale };
437	
438	export const localeKey = (user: string) => ['user', user, 'locale'] as const;
439	
440	export function getLocale(user: string): Promise<UserLocale> {
441	  return getJson<UserLocale>(`/api/users/${encodeURIComponent(user)}/locale`);
442	}
443	
444	/** Save the user's locale; refused (rejects) for a locale the app does not know. */
445	export function saveLocale(user: string, locale: string): Promise<UserLocale> {
446	  return putJson<UserLocale>(`/api/users/${encodeURIComponent(user)}/locale`, { locale });
447	}
448	
449	/** The signed-in user's locale; en until read, and when no one is signed in. */
450	export function useLocale(): Locale {
451	  const [user] = useUser();
452	  const q = useQuery({ queryKey: localeKey(user ?? ''), queryFn: () => getLocale(user!), enabled: !!user });
453	  return q.data?.locale ?? 'en';
454	}
