456	const FIGURE = /^(-?)(\d+)\.(\d{2})$/;
457	
458	/** A figure as the locale shows it: text that is wholly a number with two decimals is, under de,
459	 *  `1.234,56` (a dot every three digits, a comma before the decimals); anything else, and every
460	 *  text under en, is shown as it is. */
461	export function formatFigure(text: string, locale: Locale): string {
462	  if (locale !== 'de') return text;
463	  const m = FIGURE.exec(text);
464	  if (!m) return text;
465	  return `${m[1]}${m[2].replace(/\B(?=(\d{3})+(?!\d))/g, '.')},${m[3]}`;
466	}

