=== TakeStatement
     1	package net.officefloor.hq.app.person;
     2	
    21	
    22	/** Takes a statement of the person: records their due-total now (the sum of the due of their claims that
    23	 *  count live (open ones dated within a hold of theirs, and not bound, do not), n/a ones skipped, at most the sheet's cap less their cut total (not below 0.00); n/a when their grade has no rate on the sheet's today and none of
    24	 *  those claims keeps a settled or bound figure, or a live one at a grade no longer in force or dated on or before the sheet's today) on the sheet's today, and binds each counting claim
    25	 *  to the due it shows now, late charge and floor included (a claim already bound keeps its figure); a claim that does not
    26	 *  count live is unbound.
    27	 *  <p>Taken as of a date ({@code asof}; blank: now) on or before the sheet's today, it goes by everything as it
    28	 *  stood at the end of that date (every change made while the sheet's today was on or before it counts, every
    29	 *  later one does not), that date standing in for the sheet's today: it records that day's due-total under that
    30	 *  date and binds the claims that counted then to their figures then. Refused for a date after the sheet's
    31	 *  today, or before the person was on the sheet. */
    32	public class TakeStatement {
    33	    public void take(@RequestParam(name = "asof", required = false) String asof, @Val Person person,
    34	            PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
    35	            SettingRepository settings, PoolRepository pools) throws InvalidPersonException {
    36	        String sheetId = person.getSheetId();
    37	        LocalDate today = sheets.today(sheetId);
    38	        LocalDate on = today;
    39	        Person then = person;
    40	        List<Claim> own;
    41	        List<Rate> sheetRates;
    42	        DatedSetting floor;
    43	        Dues.Late late;
    44	        DatedSetting cap;
    45	        Map<Long, BigDecimal> cuts;
    46	        if (asof == null || asof.isBlank()) {
    47	            own = claims.listOf(sheetId, person.getId());
    48	            sheetRates = rates.list(sheetId);
    49	            floor = settings.floor(sheetId);
    50	            late = settings.late(sheetId, today);
    51	            cap = settings.cap(sheetId);
    52	            cuts = pools.cutTotals(sheetId);
    53	        } else {
    54	            try {
    55	                on = LocalDate.parse(asof.trim());
    56	            } catch (DateTimeParseException e) {
    57	                throw new InvalidPersonException("The statement date must be a date");
    58	            }
    59	            if (on.isAfter(today)) {
    60	                throw new InvalidPersonException("The statement date cannot be after the sheet's today");
    61	            }
    62	            if (people.addedAfter(sheetId, person.getId(), on)) {
    63	                throw new InvalidPersonException("The person was not on the sheet on the statement date");
    64	            }
    65	            then = people.findAsOf(sheetId, person.getId(), on);
    66	            own = claims.listOfAsOf(sheetId, person.getId(), on);
    67	            sheetRates = rates.listAsOf(sheetId, on);
    68	            floor = settings.datedAsOf(sheetId, SettingRepository.FLOOR, SettingRepository.DEFAULT_FLOOR, on);
    69	            late = settings.lateAsOf(sheetId, on);
    70	            cap = settings.capAsOf(sheetId, on);
    71	            cuts = pools.cutTotalsAsOf(sheetId, on);
    72	            person.setStatedAsOf(on.toString());
    73	        }
    74	        // The figure each counting claim is bound to, by claim id.
    75	        Map<Long, String> figures = new HashMap<>();
    76	        BigDecimal total = BigDecimal.ZERO.setScale(2);
    77	        boolean kept = false;
    78	        List<Claim> counting = new java.util.ArrayList<>();
    79	        for (Claim c : own) {
    80	            if (!then.countsLive(c)) continue;
    81	            counting.add(c);
    82	            String grade = then.gradeOn(c.getDate());
    83	            Rate rate = RateRepository.inForce(sheetRates, grade, c.getDate(), c.getId());
    84	            String live = rate == null ? null : Dues.of(c.getAmount(), rate.pct(), late.rounding(c.getRoundDate()));
    85	            String shown = Dues.shown(c, live, floor.on(c.getDate()), late);
    86	            kept |= c.getSettledDue() != null || c.isBound()
    87	                    || (rate != null && (!grade.equals(then.getGrade())
    88	                            || !LocalDate.parse(c.getDate()).isAfter(on)));
    89	            if (shown != null) total = total.add(new BigDecimal(shown));
    90	            // The due as shown is bound, late charge included: it no longer follows the sheet's today.
    91	            figures.put(c.getId(), shown);
    92	        }
    93	        for (Claim c : claims.listOf(sheetId, person.getId())) {
    94	            if (figures.containsKey(c.getId())) c.bind(true, figures.get(c.getId()));
    95	            else c.bind(false, null);
    96	            claims.updateBinding(c);
    97	        }
    98	        boolean na = RateRepository.inForce(sheetRates, then.getGrade(), on.toString()) == null && !kept;
    99	        // Their cap: the one in force on the date of their latest counting claim, less their cut total.
   100	        BigDecimal capOf = SettingRepository.capOn(cap, counting, on.toString());
   101	        if (capOf != null) capOf = Rollup.capLessCuts(capOf, cuts.get(person.getId()));
   102	        if (capOf != null && total.compareTo(capOf) > 0) total = capOf.setScale(2);
   103	        String stated = na ? null : total.toPlainString();
   104	        if (asof == null || asof.isBlank()) {
   105	            // Taken now, it records the due-total their row shows: their parts of others' shared claims
   106	            // count, and the parts others hold of theirs do not.
   107	            Rollup.Figures now = Rollup.of(sheetId, people, claims, rates, sheets, settings, pools).people()
   108	                    .get(person.getId());
   109	            if (now != null) stated = now.dueTotal();
   110	        }
   111	        person.stated(stated, on.toString(), figures.size());
   112	        people.updateStatements(person);
   113	    }
   114	}
