    10	/** A steward cancels the person's last statement: the claims it bound (every claim of theirs bound
    11	 *  now, as each statement rebinds or unbinds all of them) become live again, a figure bound by a
    12	 *  statement before it not restored; the count goes down by one and they show the statement before
    13	 *  it (or none). Refused for anyone but a steward, and for a person with no statement. */
    14	public class CancelStatement {
    15	    public void cancel(@RequestParam(name = "by", required = false) String by, @Val Person person,
    16	            PersonRepository people, ClaimRepository claims, RoleRepository roles) throws InvalidPersonException {
    17	        String sheetId = person.getSheetId();
    18	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, by == null ? "" : by))) {
    19	            throw new InvalidPersonException("Only a steward can cancel a statement");
    20	        }
    21	        if (person.getStatementCount() <= 0) {
    22	            throw new InvalidPersonException("The person has no statement to cancel");
    23	        }
    24	        for (Claim c : claims.listOf(sheetId, person.getId())) {
    25	            if (c.isStated()) {
    26	                c.bind(false, null);
    27	                claims.updateBinding(c);
    28	            }
    29	        }
    30	        people.cancelStatement(person);
    31	    }
    32	}
