  7	/** How this screen orders the people list. It lives in the URL (`sort`), so it belongs to each
  8	 *  user's own screen: `added` (list order) when the screen is first opened, and left as it is by
  9	 *  loading a sheet. */
 10	export const useSortBy = () => useSearchParam('sort', (raw): SortKey =>
 11	  (SORT_KEYS as readonly unknown[]).includes(raw) ? (raw as SortKey) : 'added');
 12	
 13	/** Names as they are compared: trimmed and lower-cased. */
 14	const nameKey = (name: string) => name.trim().toLowerCase();
 15	
 16	/** The people in the order the screen shows them. Only the screen changes: the list order (and so
 17	 *  positions, rollups and every action in list order) is left as it is. `due-total` puts n/a (null)
 18	 *  last; equal keys keep list order. */
 19	export function sortPeople<P extends Person>(people: P[], key: SortKey, dueOf: (p: P) => string | null): P[] {
 20	  if (key === 'added') return people;
 21	  const cmp: (a: P, b: P) => number =
 22	    key === 'name' ? (a, b) => { const x = nameKey(a.name), y = nameKey(b.name); return x < y ? -1 : x > y ? 1 : 0; }
 23	    : key === 'grade' ? (a, b) => (a.grade < b.grade ? -1 : a.grade > b.grade ? 1 : 0)
 24	    : (a, b) => {
 25	      const x = dueOf(a), y = dueOf(b);
 26	      if (x === null || y === null) return (x === null ? 1 : 0) - (y === null ? 1 : 0);
 27	      return Number(x) - Number(y);
 28	    };
 29	  // Array.prototype.sort is stable, so equal keys keep list order.
 30	  return [...people].sort(cmp);
 31	}
