 55	  'overdue-total', 'patrons', 'backing', 'hold', 'retired', 'terms', 'contact', 'aliases',
 56	] as const;
 57	export type Column = (typeof COLUMNS)[number];
 58	type UserColumns = { user: string; sheetId: string; hidden: string[] };
 59	
 60	const columnsKey = (sheetId: string, user: string) => ['user', user, 'columns', sheetId] as const;
 61	const path = (user: string) => `/api/users/${encodeURIComponent(user)}/columns`;
