 63	/** Whether each column is shown on the user's screen for the sheet; every one until read. */
 64	export function useColumns(sheetId: string, user: string): (c: Column) => boolean {
 65	  const q = useQuery({
 66	    queryKey: columnsKey(sheetId, user),
 67	    queryFn: () => getJson<UserColumns>(`${path(user)}?sheet=${encodeURIComponent(sheetId)}`),
 68	  });
