 73	/** A checkbox per column of the people list: saved for the signed-in user on this sheet only.
 74	 *  The screen follows the box at once; each column is saved on its own, so quick clicks cannot
 75	 *  undo one another. */
 76	export function ColumnChooser({ sheetId, user }: { sheetId: string; user: string }) {
 77	  const qc = useQueryClient();
 78	  const shown = useColumns(sheetId, user);
 79	  const key = columnsKey(sheetId, user);
 80	  const save = useMutation({
 81	    mutationKey: key,
 82	    mutationFn: (v: { column: Column; shown: boolean }) =>
 83	      putJson<UserColumns>(`${path(user)}/${v.column}?sheet=${encodeURIComponent(sheetId)}`, { shown: v.shown }),
 84	    onMutate: async (v) => {
 85	      await qc.cancelQueries({ queryKey: key });
 86	      qc.setQueryData<UserColumns>(key, (d) => {
 87	        const hidden = (d?.hidden ?? []).filter((c) => c !== v.column);
 88	        return { user, sheetId, hidden: v.shown ? hidden : [...hidden, v.column] };
 89	      });
 90	    },
 91	    // Read back once the last click is saved, so an earlier answer does not undo a later click.
 92	    onSettled: () => (qc.isMutating({ mutationKey: key }) <= 1 ? qc.invalidateQueries({ queryKey: key }) : undefined),
 93	  });
 94	  return (
 95	    <p>
 96	      Columns{' '}
 97	      {COLUMNS.map((c) => (
 98	        <label key={c}>
 99	          <input type="checkbox" data-testid={`column-${c}`} checked={shown(c)}
100	            onChange={(e) => save.mutate({ column: c, shown: e.target.checked })} />{' '}
101	          {c}{' '}
102	        </label>
103	      ))}
104	    </p>
105	  );
106	}
