125	/** One CSV value: wrapped in double quotes (any quote inside doubled) when it holds a comma, a
126	 *  quote or a line break. */
127	const csvValue = (v: string) => (/[",\r\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);
128	
129	/** Downloads `lines` (the header line first) as the CSV file `name`, each line ending with a line feed. */
130	export function downloadCsv(name: string, lines: string[][]) {
131	  const csv = lines.map((l) => l.map(csvValue).join(',') + '\n').join('');
132	  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
133	  const a = document.createElement('a');
134	  a.href = url;
135	  a.download = name;
136	  document.body.appendChild(a);
137	  a.click();
138	  a.remove();
139	  setTimeout(() => URL.revokeObjectURL(url), 0);
140	}
