    22	/** Imports each line, in order: a line whose name matches a person on the sheet (by name or alias, as
    23	 *  names are compared) updates them as {@link ApplyPerson} edits them with a blank from-date (their
    24	 *  grade from the sheet's today; their terms and contact when the line gives them): PERSON_EDITED,
    25	 *  then the ROLLUP lines of the figures that moved. Any other line adds a person as {@link AddPerson}
    26	 *  does: PERSON_ADDED, then the ROLLUP lines of their figures. Every line is first checked as the form
    27	 *  checks it (a person matched by two lines is refused too), so a refused line imports nothing. */
    28	public class ImportPeople {
    29	    public void importPeople(@PathVariable("sheetId") String sheetId,
    30	            @RequestParam(name = "by", required = false) String by, @Val ImportLines lines,
    31	            PersonRepository people, SheetRepository sheets, ClaimRepository claims, RateRepository rates,
    32	            SettingRepository settings, PoolRepository pools, GradeRepository grades, Audit audit, Out<ImportResult> result) throws InvalidPersonException {
    33	        String id = sheetId.trim();
    34	        String user = by == null ? "" : by;
    35	        List<Person> matched = new ArrayList<>();
    36	        Set<Long> matchedIds = new HashSet<>();
    37	        Set<String> tree = people.treeNames(id);
    38	        for (PersonRequest request : lines.people()) {
    39	            Person person = people.findByName(id, request.name());
    40	            matched.add(person);
    41	            // A retired grade cannot be chosen: for a new person, or as a change of a person's grade.
    42	            if (person == null || !request.grade().equals(person.getGrade())) {
    43	                grades.requireChoosable(id, request.grade());
    44	            }
    45	            if (person == null) {
    46	                if (people.nameTakenInTree(id, request.name())) {
    47	                    throw new InvalidPersonException("The name is already in use: " + request.name());
    48	                }
    49	                if (request.contact() != null && people.contactTaken(id, request.contact(), null)) {
    50	                    throw new InvalidPersonException("The contact is already in use: " + request.contact());
    51	                }
    52	                continue;
    53	            }
    54	            if (!matchedIds.add(person.getId())) {
    55	                throw new InvalidPersonException("The person is repeated in the import: " + person.getName());
    56	            }
    57	            if (tree.contains(person.getName().trim().toLowerCase(Locale.ROOT))
    58	                    || person.getAliases().stream().anyMatch((a) -> tree.contains(a.trim().toLowerCase(Locale.ROOT)))) {
    59	                throw new InvalidPersonException("The name is already in use on the sheet's tree: " + person.getName());
    60	            }
    61	            if (request.contact() != null && people.contactTaken(id, request.contact(), person.getId())) {
    62	                throw new InvalidPersonException("The contact is already in use: " + request.contact());
    63	            }
    64	        }
    65	        RecordPersonAdded added = new RecordPersonAdded();
    66	        RecordPersonEdited edited = new RecordPersonEdited();
    67	        int addedCount = 0;
    68	        int updatedCount = 0;
    69	        for (int i = 0; i < lines.people().size(); i++) {
    70	            PersonRequest request = lines.people().get(i);
    71	            Person person = matched.get(i);
    72	            Rollup before = Rollup.of(id, people, claims, rates, sheets, settings, pools);
    73	            sheets.open(id, user);
    74	            if (person == null) {
    75	                person = people.add(id, request.name(), request.grade(),
    76	                        request.terms() == null ? null : Integer.valueOf(request.terms()), request.contact(), user);
    77	                added.record(by, person, audit);
    78	                addedCount++;
    79	            } else {
    80	                if (request.terms() != null) {
    81	                    person.giveTerms(Integer.valueOf(request.terms()));
    82	                }
    83	                if (request.contact() != null) {
    84	                    person.giveContact(request.contact());
    85	                }
    86	                if (!request.grade().equals(person.getGrade())) {
    87	                    LocalDate today = sheets.today(id);
    88	                    person.giveGrade(request.grade(), today.toString(), today);
    89	                }
    90	                if (!people.update(person)) {
    91	                    throw new InvalidPersonException("The person was saved by someone else meanwhile: " + person.getName());
    92	                }
    93	                if (person.getRecorded() != null) {
    94	                    people.saveGrade(person, person.getRecorded(), user);
    95	                }
    96	                edited.record(by, person, audit);
    97	                updatedCount++;
    98	            }
    99	            for (String line : Rollup.of(id, people, claims, rates, sheets, settings, pools).changesSince(before, id, user)) {
   100	                audit.record(line);
   101	            }
   102	        }
   103	        result.set(new ImportResult(addedCount, updatedCount));
   104	    }
   105	}
