  4	/** A person's plan: an amount, a start date, every N days or else a day of the month (1 to 31), an end
  5	 *  date, how many claims it has made so far and (when listed) its next dates: the first five plan dates after
  6	 *  the sheet's today and on or before the end, leaving out the days it was paused on), whether it is paused now
  7	 *  and the changes of its amount, oldest first. */
  8	export type PlanChange = { changedOn: string; amount: string };
  9	
 10	export type Plan = { id: number; sheetId: string; personId: number; amount: string; start: string; every: number | null; day: number | null; end: string; by: string; generated: number; nextDates?: string[]; paused?: boolean; changes?: PlanChange[]; targetSheet?: string | null };
 11	
 12	export type PlanInput = { amount: string; start: string; every: string; day: string; end: string; sheet: string };
 13	
 14	export type GenerateResult = { made: number };
 15	
 16	const sheetBase = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}`;
 17	
 18	export const plansKey = (sheetId: string) => [...sheetKey(sheetId), 'plans'] as const;
 19	
 20	/** The sheet's plans, in the order they were added. */
 21	export function listPlans(sheetId: string): Promise<Plan[]> {
 22	  return getJson<Plan[]>(`${sheetBase(sheetId)}/plans`);
 23	}
 24	
 25	/** Give the person a plan; refused (rejects) for an amount the claim form would refuse, an interval that is
 26	 *  not a whole number of at least 1, a day of the month not 1 to 31 (or both or neither given), an end before the start, or a sheet that is
 27	 *  not a descendant of this one. A plan naming a sheet makes its claims there, for the person of the same name. */
 28	export function addPlan(sheetId: string, by: string, personId: number, input: PlanInput): Promise<Plan> {
 29	  return postJson<Plan>(`${sheetBase(sheetId)}/people/${personId}/plans?by=${encodeURIComponent(by)}`, input);
 30	}
 31	
 32	/** Pause the plan from the sheet's today, or resume it; refused (rejects) for pausing a paused plan or
 33	 *  resuming a running one. A plan date on or after the day paused and before the day resumed is skipped. */
 34	export function pausePlan(sheetId: string, by: string, planId: number, on: boolean): Promise<Plan> {
 35	  return postJson<Plan>(`${sheetBase(sheetId)}/plans/${planId}/${on ? 'pause' : 'resume'}?by=${encodeURIComponent(by)}`, {});
 36	}
 37	
 38	/** Change the plan's amount from the sheet's today; refused (rejects) for an amount the claim form would refuse
 39	 *  (or negative). The claims it makes from then on are of the new amount; those already made keep theirs. */
 40	export function changePlanAmount(sheetId: string, by: string, planId: number, amount: string): Promise<Plan> {
 41	  return postJson<Plan>(`${sheetBase(sheetId)}/plans/${planId}/amount?by=${encodeURIComponent(by)}`, { amount });
 42	}
