 44	/** Make the DRAFT claims every plan is due up to its end and the sheet's today, that it has not made yet. */
 45	export function generatePlans(sheetId: string, by: string): Promise<GenerateResult> {
 46	  return postJson<GenerateResult>(`${sheetBase(sheetId)}/generate-plans?by=${encodeURIComponent(by)}`, {});
 47	}
