204	/** A button that makes the claims every plan is due (see `generatePlans`), and how many it made. The
205	 *  count is cleared while it runs; a refused generate makes nothing and shows an error. */
206	export function GeneratePlans({ sheetId, user }: { sheetId: string; user: string }) {
