208	  const submitOnce = useSubmitOnce();
209	
210	  const generate = useMutation({
211	    mutationFn: () => generatePlans(sheetId, user),
212	    // Not awaited: the count shows as soon as the generate is done, never after its new rows.
213	    onSuccess: () => {
214	      void queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
215	      void queryClient.invalidateQueries({ queryKey: plansKey(sheetId) });
216	    },
217	  });
218	
219	  return (
220	    <section>
221	      <button type="button" data-testid="plan-generate" disabled={generate.isPending}
222	        onClick={() => submitOnce(() => {
223	          generate.reset();
224	          return generate.mutateAsync();
225	        })}>
226	        Generate plan claims
227	      </button>
228	      {generate.isSuccess && (
229	        <>
230	          {' '}Made <span data-testid="plan-generated-count">{generate.data.made}</span>
231	        </>
232	      )}
233	      {generate.isError && (
234	        <span data-testid="plan-generate-error">The plans' claims could not be generated.</span>
235	      )}
236	    </section>
237	  );
