252	/** The grades A, B and C, then those added in the order added, each with whether it is retired. */
253	export function listGrades(sheetId: string, live = false): Promise<SheetGrade[]> {
254	  return getJson<SheetGrade[]>(`${sheetBase(sheetId)}/grades`, live);
255	}
