257	/** The sheet's grade codes in order: every grade select, the summary and the rates list these. Read
258	 *  live: a grade, once added, is listed even while the screen shows the sheet as of an earlier date. */
259	export function useGradeCodes(sheetId: string): Grade[] {
260	  const grades = useQuery({ queryKey: liveKey(gradesKey(sheetId), true), queryFn: () => listGrades(sheetId, true) });
261	  return grades.data ? grades.data.map((g) => g.grade) : GRADES;
262	}
