264	/** Add a grade (one to three capital letters, not yet a grade); refused (rejects) for anything else.
265	 *  Resolves to the grades as they now stand. */
266	export function addGrade(sheetId: string, by: string, grade: string): Promise<SheetGrade[]> {
267	  return postJson<SheetGrade[]>(`${sheetBase(sheetId)}/grade-add?by=${encodeURIComponent(by)}`, { grade });
268	}
