270	/** Retire a grade; refused (rejects) for one already retired. Resolves to the grades as they now stand. */
271	export function retireGrade(sheetId: string, by: string, grade: string): Promise<SheetGrade[]> {
272	  return postJson<SheetGrade[]>(`${sheetBase(sheetId)}/grade-retire?by=${encodeURIComponent(by)}`, { grade });
273	}
