278	/** Merge a grade into another: everyone on it today is given the other from the sheet's today, and
279	 *  retroactively every grade record of theirs on it becomes the other.
280	 *  Refused (rejects) for the same grade twice, or for anyone but a steward. */
281	export function mergeGrade(sheetId: string, by: string, from: string, into: string): Promise<GradeMerged> {
282	  return postJson<GradeMerged>(`${sheetBase(sheetId)}/grade-merge?by=${encodeURIComponent(by)}`, { from, into });
