292	/** The sheet's grades, each shown retired or not; an entry and button to add one (one to three capital
293	 *  letters, not yet a grade), and a select and button to retire one. A retired
294	 *  grade cannot be chosen for a new person or in an edit; people already on it keep it. A steward can
295	 *  merge a grade into another (two selects and a button), and sees how many people it regraded. */
296	export function Grades({ sheetId, user }: { sheetId: string; user: string }) {
297	  const gradeCodes = useGradeCodes(sheetId);
298	  const queryClient = useQueryClient();
299	  const grades = useQuery({ queryKey: gradesKey(sheetId), queryFn: () => listGrades(sheetId) });
300	  const [grade, setGrade] = useState<string>(GRADES[0]);
301	
302	  const retire = useMutation({
303	    mutationFn: (input: string) => retireGrade(sheetId, user, input),
304	    onSuccess: (data) => {
305	      queryClient.setQueryData(gradesKey(sheetId), data);
306	      return queryClient.invalidateQueries({ queryKey: gradesKey(sheetId) });
307	    },
308	  });
309	
310	  const [code, setCode] = useState('');
311	  const add = useMutation({
312	    mutationFn: (input: string) => addGrade(sheetId, user, input),
313	    onSuccess: (data) => {
314	      setCode('');
315	      queryClient.setQueryData(gradesKey(sheetId), data);
316	      queryClient.setQueryData(liveKey(gradesKey(sheetId), true), data);
317	      return Promise.all([
318	        queryClient.invalidateQueries({ queryKey: gradesKey(sheetId) }),
319	        queryClient.invalidateQueries({ queryKey: liveKey(gradesKey(sheetId), true) }),
