328	    onSuccess: () => Promise.all([
329	      queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
330	      queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
331	    ]),
332	  });
333	
334	  const submitOnce = useSubmitOnce();
335	  const addOnce = useSubmitOnce();
336	  const mergeOnce = useSubmitOnce();
337	
338	  return (
339	    <section>
340	      <h3>Grades</h3>
341	      <form
342	        onSubmit={(e) => {
343	          e.preventDefault();
344	          const input = code;
345	          addOnce(() => {
346	            add.reset();
347	            retire.reset();
348	            merge.reset();
349	            return add.mutateAsync(input);
350	          });
351	        }}
