361	        {add.isError && (
362	          <span data-testid="grade-error">A grade is one to three capital letters, not yet a grade.</span>
363	        )}
364	      </form>
365	      <form
366	        onSubmit={(e) => {
367	          e.preventDefault();
368	          const input = grade;
369	          submitOnce(() => {
370	            retire.reset();
371	            merge.reset();
372	            add.reset();
373	            return retire.mutateAsync(input);
374	          });
375	        }}
376	      >
377	        <select data-testid="grade-retire-select" value={grade}
378	          onChange={(e) => {
379	            setGrade(e.target.value);
380	            retire.reset();
381	          }}>
382	          {gradeCodes.map((g) => <option key={g} value={g}>{g}</option>)}
383	        </select>{' '}
384	        <button type="submit" data-testid="grade-retire" disabled={retire.isPending}>
385	          Retire grade
386	        </button>
387	        {retire.isError && (
388	          <span data-testid="grade-error">That grade is already retired.</span>
389	        )}
390	      </form>
391	      <div>
392	        Merge{' '}
393	        <select data-testid="grade-merge-from" value={mergeFrom}
394	          onChange={(e) => {
395	            setMergeFrom(e.target.value);
396	            merge.reset();
397	          }}>
398	          {gradeCodes.map((g) => <option key={g} value={g}>{g}</option>)}
399	        </select>{' '}
400	        into{' '}
401	        <select data-testid="grade-merge-into" value={mergeInto}
402	          onChange={(e) => {
403	            setMergeInto(e.target.value);
404	            merge.reset();
405	          }}>
406	          {gradeCodes.map((g) => <option key={g} value={g}>{g}</option>)}
407	        </select>{' '}
408	        <button type="button" data-testid="grade-merge" disabled={merge.isPending}
409	          onClick={() => {
410	            const v = { from: mergeFrom, into: mergeInto };
411	            mergeOnce(() => {
412	              merge.reset();
413	              retire.reset();
414	              add.reset();
415	              return merge.mutateAsync(v);
416	            });
417	          }}>
418	          Merge grade
419	        </button>
420	        {merge.isSuccess && (
421	          <>
422	            {' '}Regraded <span data-testid="grade-merged">{merge.data.merged}</span>
423	          </>
424	        )}
425	        {merge.isError && (
426	          <span data-testid="grade-error">The grade could not be merged: pick two different grades (stewards only).</span>
427	        )}
428	      </div>
429	      <table>
430	        <tbody>
431	          {(grades.data ?? []).map((g) => (
432	            <tr key={g.grade} data-testid={`grade-row-${g.grade}`}>
433	              <td>{g.grade}</td>
434	              <td data-testid="grade-retired">{g.retired ? 'yes' : 'no'}</td>
435	            </tr>
436	          ))}
437	        </tbody>
438	      </table>
439	    </section>
440	  );
441	}

