    public void updateFlag(Person person) {
        jdbc.update("UPDATE person SET flag_reason = ?, flag_until = ? WHERE sheet_id = ? AND id = ?",
                person.getFlagReason(), LocalDate.parse(person.getFlagUntil()), person.getSheetId(), person.getId());
    }

    /** Add a hold on the person (not an edit: the version stays). */
    public void addHold(Person person, Hold hold, String user) {
        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date, held_by, added_on) "
                + "VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
                person.getSheetId(), person.getId(), LocalDate.parse(hold.from()),
                hold.to() == null ? null : LocalDate.parse(hold.to()), user, person.getSheetId());
        person.getHolds().add(hold);
    }

    /** Merge the person {@code from} into {@code into}: from's name and aliases become into's aliases;
     *  from's patrons are added to into's (not into themselves, no repeats); anyone naming from as
     *  patron names into instead (no repeats); into's statement count becomes theirs plus from's, their
     *  last statement staying theirs (having none, becoming from's), from's statements kept before
     *  into's; from's holds, watchers, grades and the person themselves are dropped; from's plans and crews become into's. Their claims, pool memberships and period totals must have
     *  moved first ({@code claimIds}: the claims that moved). The merge is kept as the last into
     *  {@code into}, with what it takes from from, for {@link #undoMerge} when {@code undoable}. */
    public void merge(Person from, Person into, String user, List<Long> claimIds, boolean undoable) {
        String sheetId = into.getSheetId();
        GeneratedKeyHolder mergeKey = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement("INSERT INTO person_merge (sheet_id, from_id, from_name, into_id, "
                    + "merged_by, merged_on, undoable) VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?), ?)",
                    new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setLong(2, from.getId());
            ps.setString(3, from.getName());
            ps.setLong(4, into.getId());
            ps.setString(5, user);
            ps.setString(6, sheetId);
            ps.setBoolean(7, undoable);
            return ps;
        }, mergeKey);
        long mergeId = mergeKey.getKey().longValue();
        if (undoable) {
            for (Long claimId : claimIds) {
                jdbc.update("INSERT INTO person_merge_moved (merge_id, kind, ref) VALUES (?, 'CLAIM', ?)", mergeId, claimId);
            }
            jdbc.update("INSERT INTO person_merge_moved (merge_id, kind, ref) SELECT ?, 'ALIAS', id FROM person_alias "
                    + "WHERE sheet_id = ? AND person_id = ?", mergeId, sheetId, from.getId());
            for (String table : MERGE_KEPT) {
                keep(mergeId, table, sheetId, from.getId());
            }
        }
        GeneratedKeyHolder aliasKey = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person_alias (sheet_id, person_id, alias, added_by) VALUES (?, ?, ?, ?)", new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setLong(2, into.getId());
            ps.setString(3, from.getName());
            ps.setString(4, user);
            return ps;
        }, aliasKey);
        jdbc.update("UPDATE person_merge SET name_alias_id = ? WHERE id = ?", aliasKey.getKey().longValue(), mergeId);
        jdbc.update("UPDATE person_alias SET person_id = ? WHERE sheet_id = ? AND person_id = ?",
                into.getId(), sheetId, from.getId());
        for (Long patronId : from.getPatronIds()) {
            if (patronId != into.getId() && !into.getPatronIds().contains(patronId)) {
                jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id, added_by) VALUES (?, ?, ?, ?)",
                        sheetId, into.getId(), patronId, user);
                into.getPatronIds().add(patronId);
            }
        }
        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND person_id = ?", sheetId, from.getId());
        // Whoever named from names into instead, unless that is into themselves or they name into already.
        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND patron_id = ? AND (person_id = ? OR person_id IN "
                + "(SELECT k.person_id FROM person_patron k WHERE k.sheet_id = ? AND k.patron_id = ?))",
                sheetId, from.getId(), into.getId(), sheetId, into.getId());
        jdbc.update("UPDATE person_patron SET patron_id = ? WHERE sheet_id = ? AND patron_id = ?",
                into.getId(), sheetId, from.getId());
        into.getPatronIds().remove(Long.valueOf(from.getId()));
        // from's statements go before into's, so into's last stays their last.
        List<Long> own = jdbc.queryForList("SELECT id FROM person_statement WHERE sheet_id = ? AND person_id = ? ORDER BY id",
                Long.class, sheetId, into.getId());
        jdbc.update("UPDATE person_statement SET person_id = ? WHERE sheet_id = ? AND person_id = ?",
                into.getId(), sheetId, from.getId());
        for (Long id : own) {
            jdbc.update("INSERT INTO person_statement (sheet_id, person_id, stated_total, statement_date, taken_at) "
                    + "SELECT sheet_id, person_id, stated_total, statement_date, taken_at FROM person_statement WHERE id = ?", id);
            jdbc.update("DELETE FROM person_statement WHERE id = ?", id);
        }
        into.absorbStatements(from);
        saveStatements(into);
        for (String table : List.of("person_hold", "person_watch", "person_grade", "person_terms",
                "person_grade_history", "person_retired_history", "person_retirement")) {
            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", sheetId, from.getId());
        }
        // from's plans go on making claims, now for into.
        jdbc.update("UPDATE plan SET person_id = ? WHERE sheet_id = ? AND person_id = ?", into.getId(), sheetId, from.getId());
        // from's crews become into's: crews from leads into leads; from's memberships move to into, unless
        // into is in that crew already or leads it.
        jdbc.update("UPDATE crew SET lead_id = ? WHERE sheet_id = ? AND lead_id = ?", into.getId(), sheetId, from.getId());
        jdbc.update("DELETE FROM crew_member WHERE sheet_id = ? AND person_id = ? AND crew_id IN "
                + "(SELECT m.crew_id FROM crew_member m WHERE m.person_id = ?)", sheetId, from.getId(), into.getId());
        jdbc.update("UPDATE crew_member SET person_id = ? WHERE sheet_id = ? AND person_id = ?", into.getId(), sheetId, from.getId());
        jdbc.update("DELETE FROM crew_member WHERE sheet_id = ? AND person_id = ? AND crew_id IN "
                + "(SELECT c.id FROM crew c WHERE c.lead_id = ?)", sheetId, into.getId(), into.getId());
        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, from.getId());
        withAliases(sheetId, List.of(into));
    }

    /** The person's own rows a merge drops with them, kept for an undo: the person first. */
    private static final List<String> MERGE_KEPT = List.of("person", "person_grade", "person_terms",
            "person_grade_history", "person_retired_history", "person_retirement", "person_hold", "person_watch");

    /** Keep the person's rows of the table (each column's value as text) under the merge. */
    private void keep(long mergeId, String table, String sheetId, long personId) {
        List<String> generated = jdbc.queryForList("SELECT LOWER(COLUMN_NAME) FROM INFORMATION_SCHEMA.COLUMNS "
                + "WHERE TABLE_SCHEMA = 'PUBLIC' AND TABLE_NAME = ? AND IS_GENERATED = 'ALWAYS'", String.class,
                table.toUpperCase(java.util.Locale.ROOT));
        List<List<String[]>> rows = new ArrayList<>();
        jdbc.query("SELECT * FROM " + table + " WHERE sheet_id = ? AND " + ("person".equals(table) ? "id" : "person_id") + " = ?",
                (rs) -> {
                    java.sql.ResultSetMetaData md = rs.getMetaData();
                    List<String[]> row = new ArrayList<>();
                    for (int i = 1; i <= md.getColumnCount(); i++) {
                        String col = md.getColumnLabel(i).toLowerCase(java.util.Locale.ROOT);
                        if (!generated.contains(col)) {
                            row.add(new String[] { col, rs.getString(i) });
                        }
                    }
                    rows.add(row);
                }, sheetId, personId);
        for (int n = 0; n < rows.size(); n++) {
            for (String[] value : rows.get(n)) {
                jdbc.update("INSERT INTO person_merge_value (merge_id, tbl, row_no, col, val) VALUES (?, ?, ?, ?, ?)",
                        mergeId, table, n, value[0], value[1]);
            }
        }
    }

    /** The last merge into the person on the sheet; null when there has been none. */
    public PersonMerge lastMergeInto(String sheetId, long intoId) {
        return jdbc.query("SELECT id, from_id, from_name, merged_by, merged_on, undoable, undone, name_alias_id "
                + "FROM person_merge WHERE sheet_id = ? AND into_id = ? ORDER BY id DESC",
                (rs, n) -> new PersonMerge(rs.getLong("id"), sheetId, rs.getLong("from_id"), rs.getString("from_name"),
                        intoId, rs.getString("merged_by"), rs.getObject("merged_on", LocalDate.class),
                        rs.getBoolean("undoable"), rs.getBoolean("undone"), rs.getObject("name_alias_id", Long.class)),
                sheetId, intoId).stream().findFirst().orElse(null);
    }

    /** The claims the merge moved from the merged person. */
    public List<Long> mergedClaims(PersonMerge merge) {
        return jdbc.queryForList("SELECT ref FROM person_merge_moved WHERE merge_id = ? AND kind = 'CLAIM' ORDER BY ref",
                Long.class, merge.id());
    }

    /** Undo the merge: the merged person is back, as they were merged, at the end of the list, with
     *  their own aliases (those the other still has) and without the alias their name became; the merge
     *  is marked undone. Their claims are given back separately (see ClaimRepository#moveBack). */
    public void undoMerge(PersonMerge merge) {
        String sheetId = merge.sheetId();
        Map<String, Map<Integer, Map<String, String>>> kept = new java.util.LinkedHashMap<>();
        MERGE_KEPT.forEach((t) -> kept.put(t, new java.util.TreeMap<>()));
        jdbc.query("SELECT tbl, row_no, col, val FROM person_merge_value WHERE merge_id = ?", (rs) -> {
            kept.computeIfAbsent(rs.getString("tbl"), (t) -> new java.util.TreeMap<>())
                    .computeIfAbsent(rs.getInt("row_no"), (n) -> new java.util.LinkedHashMap<>())
                    .put(rs.getString("col"), rs.getString("val"));
        }, merge.id());
        kept.forEach((table, rows) -> rows.values().forEach((row) -> {
            List<String> cols = new ArrayList<>(row.keySet());
            jdbc.update("INSERT INTO " + table + " (" + String.join(", ", cols) + ") VALUES ("
                    + String.join(", ", java.util.Collections.nCopies(cols.size(), "?")) + ")",
                    cols.stream().map(row::get).toArray());
        }));
        jdbc.update("UPDATE person SET list_pos = " + NEXT_POS + " WHERE sheet_id = ? AND id = ?",
                sheetId, sheetId, merge.fromId());
        jdbc.update("UPDATE person_alias SET person_id = ? WHERE sheet_id = ? AND person_id = ? AND id IN "
                + "(SELECT ref FROM person_merge_moved WHERE merge_id = ? AND kind = 'ALIAS')",
                merge.fromId(), sheetId, merge.intoId(), merge.id());
        if (merge.nameAliasId() != null) {
            jdbc.update("DELETE FROM person_alias WHERE sheet_id = ? AND id = ?", sheetId, merge.nameAliasId());
        }
        jdbc.update("DELETE FROM person_merge_value WHERE merge_id = ?", merge.id());
        jdbc.update("UPDATE person_merge SET undone = TRUE WHERE id = ?", merge.id());
    }

    /** Move the person to the sheet {@code to} with their grades (and grade history) and aliases, their
     *  statements dropped (the count back to 0) and their plans going with them; their holds, watchers, patron links (either way), pool
     *  and crew memberships and closed periods' fixed totals are dropped (crews they lead stay, without a lead); they keep the sheet they came from as their
     *  origin. When {@code merging} (they are to be merged into someone there straight after) they keep
     *  their statements and arrive under a stand-in name, as theirs is taken there. Their claims must
     *  have moved first. They are marked as arriving on {@code arrivedOn}, the sheet {@code to}'s today. */
    public void transfer(Person person, String to, boolean merging, LocalDate arrivedOn) {
        String sheetId = person.getSheetId();
        long id = person.getId();
        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND (person_id = ? OR patron_id = ?)", sheetId, id, id);
        for (String table : List.of("person_hold", "person_watch", "pool_member", "crew_member")) {
            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", sheetId, id);
        }
        // A crew they lead stays, without a lead.
        jdbc.update("UPDATE crew SET lead_id = NULL WHERE sheet_id = ? AND lead_id = ?", sheetId, id);
        // Statements kept from leaving any sheet but the one they go to (an undo gives those back) go.
        for (String table : List.of("person_left", "person_statement_left")) {
            jdbc.update("DELETE FROM " + table + " WHERE person_id = ? AND (sheet_id <> ? OR ?)", id, to, merging);
        }
        if (merging) {
            jdbc.update("UPDATE person_statement SET sheet_id = ? WHERE sheet_id = ? AND person_id = ?", to, sheetId, id);
        } else {
            jdbc.update("INSERT INTO person_left (sheet_id, person_id, statement_count, stated_total, statement_date) "
                    + "SELECT sheet_id, id, statement_count, stated_total, statement_date FROM person WHERE sheet_id = ? AND id = ?", sheetId, id);
            jdbc.update("INSERT INTO person_statement_left (sheet_id, person_id, stated_total, statement_date, taken_at) "
                    + "SELECT sheet_id, person_id, stated_total, statement_date, taken_at FROM person_statement "
                    + "WHERE sheet_id = ? AND person_id = ? ORDER BY id", sheetId, id);
            jdbc.update("DELETE FROM person_statement WHERE sheet_id = ? AND person_id = ?", sheetId, id);
            jdbc.update("UPDATE person SET statement_count = 0, stated_total = NULL, statement_date = NULL "
                    + "WHERE sheet_id = ? AND id = ?", sheetId, id);
        }
        jdbc.update("DELETE FROM period_person_total WHERE person_id = ?", id);
        jdbc.update("DELETE FROM period_opening WHERE person_id = ?", id);
        for (String table : List.of("person_grade", "person_terms", "person_grade_history", "person_retired_history", "person_retirement", "person_alias", "plan")) {
            jdbc.update("UPDATE " + table + " SET sheet_id = ? WHERE sheet_id = ? AND person_id = ?", to, sheetId, id);
        }
        String name = merging ? "#merging-" + id : person.getName();
        jdbc.update("UPDATE person SET sheet_id = ?, name = ?, "
                + "origin = ?, arrived_on = ?, list_pos = " + NEXT_POS + " WHERE sheet_id = ? AND id = ?",
                to, name, sheetId, arrivedOn, to, sheetId, id);
    }

    /** Give the person, transferred back to the sheet they last left, the statements that transfer
     *  dropped from them there. */
    public void restoreStatements(String sheetId, long id) {
        jdbc.update("INSERT INTO person_statement (sheet_id, person_id, stated_total, statement_date, taken_at) "
                + "SELECT sheet_id, person_id, stated_total, statement_date, taken_at FROM person_statement_left "
                + "WHERE sheet_id = ? AND person_id = ? ORDER BY id", sheetId, id);
        jdbc.update("UPDATE person p SET (statement_count, stated_total, statement_date) = "
                + "(SELECT l.statement_count, l.stated_total, l.statement_date FROM person_left l WHERE l.sheet_id = p.sheet_id AND l.person_id = p.id) "
                + "WHERE p.sheet_id = ? AND p.id = ? AND EXISTS (SELECT 1 FROM person_left l WHERE l.sheet_id = p.sheet_id AND l.person_id = p.id)", sheetId, id);
        for (String table : List.of("person_left", "person_statement_left")) {
            jdbc.update("DELETE FROM " + table + " WHERE person_id = ?", id);
        }
    }

    /** Swap the two people's places in their sheet's list. */
    public void swap(String sheetId, long a, long b) {
        Long posA = jdbc.queryForObject("SELECT list_pos FROM person WHERE sheet_id = ? AND id = ?", Long.class, sheetId, a);
        Long posB = jdbc.queryForObject("SELECT list_pos FROM person WHERE sheet_id = ? AND id = ?", Long.class, sheetId, b);
        jdbc.update("UPDATE person SET list_pos = ? WHERE sheet_id = ? AND id = ?", posB, sheetId, a);
        jdbc.update("UPDATE person SET list_pos = ? WHERE sheet_id = ? AND id = ?", posA, sheetId, b);
    }
}

/** A reference compared without regard to case (null: none). */
private static String refKey(String ref) {
    return ref == null ? null : ref.toLowerCase(Locale.ROOT);
}

/** Refuse a reference (null: none, always free) that a claim on the sheet other than {@code exceptId}
 *  (0: none) already has, compared without regard to case. */
public void requireRefFree(String sheetId, String ref, long exceptId) throws InvalidClaimException {
    if (ref == null) return;
    Integer used = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND ref_key = ? AND id <> ?",
            Integer.class, sheetId, refKey(ref), exceptId);
    if (used != null && used > 0) {
        throw new InvalidClaimException("The reference is already used on the sheet: " + ref);
    }
}

public void update(Claim claim) {
    jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, number = ?, settled_due = ?, opened_by = ?, corrects = ?, ref = ?, ref_key = ?, tags = ?, void_reason = ?, edited_by = ?, settle_batch = ? WHERE sheet_id = ? AND id = ?",
            new BigDecimal(claim.getAmount()), LocalDate.parse(claim.getDate()), claim.getNote(),
            claim.getStatus(), claim.getNumber(),
            claim.getSettledDue() == null ? null : new BigDecimal(claim.getSettledDue()),
            claim.getOpenedBy(), claim.getCorrects(), claim.getRef(), refKey(claim.getRef()), claim.getTags(),
            claim.getVoidReason(), claim.getEditedBy(), claim.getSettleBatch(), claim.getSheetId(), claim.getId());
    snapshot(claim.getSheetId(), claim.getId());
    useTags(claim.getSheetId(), claim.getTags());
}

/** Keep each of the tags (comma separated; null: none) among those ever used on the sheet. */
private void useTags(String sheetId, String tags) {
    if (tags == null) return;
    for (String tag : tags.split(",")) {
        jdbc.update("MERGE INTO sheet_tag (sheet_id, tag) KEY (sheet_id, tag) VALUES (?, ?)", sheetId, tag);
    }
}

/** Every tag ever used on the sheet, sorted. */
public List<String> tags(String sheetId) {
    return jdbc.queryForList("SELECT tag FROM sheet_tag WHERE sheet_id = ? ORDER BY tag", String.class, sheetId);
}

/** Save a claim moved to another person: its person, its number (renumbered), its binding
 *  (dropped), and its place in the list, now the newest. */
public void reassign(Claim claim) {
    jdbc.update("UPDATE claim SET person_id = ?, number = ?, stated = ?, stated_due = ?, list_seq = "
            + NEXT_SEQ + " WHERE sheet_id = ? AND id = ?",
            claim.getPersonId(), claim.getNumber(), claim.isStated(),
            claim.getStatedDue() == null ? null : new BigDecimal(claim.getStatedDue()),
            claim.getSheetId(), claim.getSheetId(), claim.getId());
    snapshot(claim.getSheetId(), claim.getId());
}

/** Move every claim of the person {@code fromId} to {@code intoId}, in the order they were added,
 *  each the newest in the list as it moves: their numbers and dates kept, and any figure a statement
 *  bound them to kept. The ids of the claims moved come back, in that order. */
public List<Long> moveAll(String sheetId, long fromId, long intoId) {
    List<Long> moved = jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY id",
            Long.class, sheetId, fromId);
    for (Long id : moved) {
        jdbc.update("UPDATE claim SET person_id = ?, list_seq = "
                + NEXT_SEQ + " WHERE sheet_id = ? AND id = ?", intoId, sheetId, sheetId, id);
        snapshot(sheetId, id);
    }
    return moved;
}

/** Give back the claims a merge moved from the person {@code toId} to {@code fromId}, those still
 *  {@code fromId}'s, as they are now (numbers, status and place in the list kept). */
public void moveBack(String sheetId, List<Long> ids, long fromId, long toId) {
    for (Long id : ids) {
        if (jdbc.update("UPDATE claim SET person_id = ? WHERE sheet_id = ? AND id = ? AND person_id = ?",
                toId, sheetId, id, fromId) > 0) {
            snapshot(sheetId, id);
        }
    }
}

/** Move every claim of the person to the sheet {@code to}, with their logs, comments and history,
 *  keeping their order in the list (each newer than the other sheet's): their status, dates, notes,
 *  tags, frozen figures and any figure a statement bound them to kept, their reference, lock and
 *  settle batch dropped, and their numbers taken away. The ids of those that had a number come back in
 *  the order they were opened (by the sheet's today then, then the order they were added), for
 *  {@link #renumber}. */
public List<Long> transferAll(String sheetId, long personId, String to) {
    List<Long> numbered = jdbc.queryForList("SELECT c.id FROM claim c WHERE c.sheet_id = ? AND c.person_id = ? "
            + "AND c.number IS NOT NULL ORDER BY COALESCE((SELECT MIN(l.on_date) FROM claim_log l WHERE "
            + "l.claim_id = c.id AND l.status = 'OPEN'), (SELECT MIN(l.on_date) FROM claim_log l WHERE "
            + "l.claim_id = c.id AND l.status <> 'DRAFT'), c.claim_date), c.id", Long.class, sheetId, personId);
    long seq = jdbc.queryForObject("SELECT COALESCE(MAX(list_seq), 0) FROM claim WHERE sheet_id = ?", Long.class, to);
    for (Long id : jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY list_seq, id",
            Long.class, sheetId, personId)) {
        jdbc.update("UPDATE claim SET sheet_id = ?, list_seq = ?, number = NULL, "
                + "ref = NULL, ref_key = NULL, locked_by = NULL, settle_batch = NULL WHERE sheet_id = ? AND id = ?",
                to, ++seq, sheetId, id);
        for (String table : List.of("claim_log", "claim_comment", "claim_line", "claim_share", "claim_history")) {
            jdbc.update("UPDATE " + table + " SET sheet_id = ? WHERE sheet_id = ? AND claim_id = ?", to, sheetId, id);
        }
        snapshot(to, id);
        useTags(to, jdbc.queryForObject("SELECT tags FROM claim WHERE id = ?", String.class, id));
    }
    return numbered;
}

/** Give a transferred claim its number on its new sheet. */
public void renumber(Claim claim, String number) {
    jdbc.update("UPDATE claim SET number = ? WHERE sheet_id = ? AND id = ?", number, claim.getSheetId(), claim.getId());
    claim.setNumber(number);
}

/** Save a re-dated claim: its date (its due-by, period and number stay). */
public void redate(Claim claim) {
    jdbc.update("UPDATE claim SET claim_date = ?, number = ? WHERE sheet_id = ? AND id = ?",
            LocalDate.parse(claim.getDate()), claim.getNumber(), claim.getSheetId(), claim.getId());
    snapshot(claim.getSheetId(), claim.getId());
}

/** Save a claim's due-by set directly: it stays as set (see {@link #refixDueBys}). */
public void setDueBy(Claim claim) {
    jdbc.update("UPDATE claim SET due_by = ?, due_by_set = TRUE WHERE sheet_id = ? AND id = ?",
            LocalDate.parse(claim.getDueBy()), claim.getSheetId(), claim.getId());
    snapshot(claim.getSheetId(), claim.getId());
}

/** Work out again, after a holiday was added, the due-by of every claim on the sheet that is not
 *  SETTLED or VOID and is due by the holiday or later: from its date, with the terms it was fixed
 *  with, past the sheet's holidays now. A claim whose due-by a steward set directly keeps it. A claim whose due-by moves is kept in its history. */
public void refixDueBys(String sheetId, LocalDate holiday) {
    Set<LocalDate> holidays = holidays(sheetId);
    jdbc.query("SELECT id, claim_date, terms, due_by FROM claim WHERE sheet_id = ? "
            + "AND status NOT IN ('SETTLED', 'VOID', 'DELETED') AND NOT due_by_set AND due_by >= ? ORDER BY id", (rs) -> {
                long id = rs.getLong("id");
                LocalDate dueBy = BusinessDays.dueBy(rs.getObject("claim_date", LocalDate.class),
                        rs.getInt("terms"), holidays);
                if (!dueBy.equals(rs.getObject("due_by", LocalDate.class))) {
                    jdbc.update("UPDATE claim SET due_by = ? WHERE sheet_id = ? AND id = ?", dueBy, sheetId, id);
                    snapshot(sheetId, id);
                }
            }, sheetId, holiday);
}

private Set<LocalDate> holidays(String sheetId) {
    return new HashSet<>(jdbc.queryForList("SELECT holiday FROM holiday WHERE sheet_id = ?", LocalDate.class, sheetId));
}

/** The person's claims, newest first. */
public List<Claim> listOf(String sheetId, long personId) {
    return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY list_seq DESC, id DESC",
            ROW, sheetId, personId);
}

