    /** Refuses opening a claim that belongs to a period with a cap (its due-by falls in it) when its
     *  person already has that many OPEN or PENDING claims in the period; shared with {@link BulkOpenClaims}. */
    static void requireUnderCap(Claim claim, ClaimRepository claims, PeriodRepository periods)
            throws ClaimStatusException {
        Period period = periods.containing(claim.getSheetId(), claim.getDueBy());
        if (period == null || period.cap() == null) return;
        long held = claims.list(claim.getSheetId()).stream()
                .filter((c) -> c.getId() != claim.getId() && c.getPersonId() == claim.getPersonId()
                        && ClaimStatus.isOpen(c.getStatus()) && period.contains(c.getDueBy()))
                .count();
        if (held >= period.cap()) {
            throw new ClaimStatusException("The person already has " + period.cap()
                    + " open claims in period " + period.name());
        }
    }

    /** Refuses opening a claim when its person already has as many OPEN or PENDING claims as the
     *  sheet's maximum of open claims (blank: none); shared with {@link BulkOpenClaims}. */
    static void requireUnderMaxOpen(Claim claim, ClaimRepository claims, SettingRepository settings)
            throws ClaimStatusException {
        Integer max = settings.maxOpen(claim.getSheetId());
        if (max == null) return;
        return dates.isEmpty() ? null : dates.get(0);
    }

    /** Each logged claim's status at the end of the day, as its log records it: the last status
     *  logged on or before it, or null when it was added after it. Claims with no log are absent. */
    public Map<Long, String> statusesOn(String sheetId, LocalDate date) {
        Map<Long, String> statuses = new HashMap<>();
        jdbc.query("SELECT claim_id, status, on_date FROM claim_log WHERE sheet_id = ? ORDER BY id",
                (rs) -> {
                    long claimId = rs.getLong("claim_id");
                    if (!rs.getObject("on_date", LocalDate.class).isAfter(date)) {
                        statuses.put(claimId, rs.getString("status"));
                    } else {
                        statuses.putIfAbsent(claimId, null);
                    }
                }, sheetId);
        return statuses;
    }

    /** Give each claim its log lines. */
    public List<Claim> withLogs(String sheetId, List<Claim> claims) {
        Map<Long, List<String>> lines = linesOf(sheetId);
        for (Claim c : claims) c.setLog(lines.getOrDefault(c.getId(), List.of()));
        return claims;
    }
